/**
 * Obtener índice de talento.
 *
 * @param int $id ID del proceso.
 * @param int $aplicante_id ID del aplicante.
 * @return object
 * @author Daniel Beltrán
 */
public function obtenerIndiceTalento(int $id, int $aplicante_id): object {
    return DB::select('SELECT fn_indice_talento(?, ?) AS indice_talento', [$id, $aplicante_id])[0];
}

/**
 * Verificar si un usuario ya está seleccionado en un proceso.
 *
 * @param int $proceso_id ID del proceso.
 * @param int $usuario_id ID del usuario.
 * @return bool
 * @author Daniel Beltrán
 */
public function estaSeleccionado(int $proceso_id, int $usuario_id): bool {
    return $this->modelo->find($proceso_id)
    ->seleccionados()
    ->where('usuario_id', $usuario_id)
    ->exists();
}

/**
 * Agregar un participante a la lista de seleccionados.
 *
 * @param int $proceso_id ID del proceso.
 * @param int $usuario_id ID del usuario.
 * @param array $datos_pivot Datos adicionales para la tabla pivot.
 * @return void
 * @author Daniel Beltrán
 */
public function agregarSeleccionado(int $proceso_id, int $usuario_id, array $datos_pivot = []): void {
    $this->modelo->find($proceso_id)->seleccionados()->attach($usuario_id, $datos_pivot);
}

