   506→    /**
   507→     * Obtener usuarios de una empresa (y sucursales activas) con filtros y relaciones opcionales.
   508→     *
   509→     * Esta consulta retorna los usuarios que tengan relación en `empresas_usuarios` con la empresa indicada
   510→     * o cualquiera de sus sucursales activas. Permite cargar relaciones útiles para renderizar en la UI y
   511→     * aplicar filtros por tipo de rol. Adicionalmente, soporta colapsar múltiples roles por usuario a un
   512→     * único rol “de mayor jerarquía” (rol con id más bajo), excluyendo el rol Evaluado.
   513→     *
   514→     * Parámetros soportados en `$request`:
   515→     * - `con_relaciones` (bool): si true, carga relaciones de usuario como `cargo`, `estado`, `ciudad` y
   516→     *   `empresasUsuarios.rol`/`empresasUsuarios.empresa`.
   517→     * - `validar_relaciones` (bool): si true, agrega `withExists` para banderas de uso (`tiene_agendas`,
   518→     *   `tiene_ofertas_laborales`, `tiene_procesos`, `tiene_etapa_usuario`).
   519→     * - `con_rol_tipo_empresa` (bool): si true, filtra por roles de tipo empresa [4, 6, 7, 8].
   520→     * - `con_rol_tipo_superadmin` (bool): si true, filtra por roles de tipo superadmin [1, 2, 3, 5].
   521→     * - `en`, `campo`, `valores`: cuando `en=true` y se proveen `campo` y `valores`, aplica `whereIn(campo, valores)`.
   522→     * - `solo_rol_mas_alto` (bool): si true y `con_relaciones=true`, post-procesa cada usuario para dejar una sola
   523→     *   relación en `empresasUsuarios`, seleccionando la de menor `rol_id` dentro de las empresas relevantes y
   524→     *   excluyendo el rol Evaluado (`rol_id = 9`). Esto evita mostrar duplicados por múltiples roles y prioriza el
   525→     *   rol de mayor nivel en contexto empresa.
   526→     *
   527→     * Notas de implementación:
   528→     * - Se unifica el manejo de empresa matriz vs. sucursal construyendo un arreglo `empresa_ids` con la empresa
   529→     *   actual y, si aplica, sus sucursales activas.
   530→     * - El post-proceso de `solo_rol_mas_alto` actúa únicamente cuando se cargan relaciones (`con_relaciones=true`).
   531→     *
   532→     * @param Request $request Contenido de la petición.
   533→     * @param Empresa|int $empresa Id o instancia de la empresa objetivo.
   534→     * @return ?Collection Colección de usuarios o null si la empresa no está activa.
   535→     * @author Fahibram Cárcamo
   536→     * @author Andres Gonzalez
   537→     * @author Sergio Vargas
   538→     * @author Esperanza Olivo
   539→     * @author José Manuel Jiménez
   540→     */
   541→    public function obtenerUsuariosSucursalesEmpresa(Request $request, int|Empresa $empresa): ?Collection {
   542→        $empresa = gettype($empresa) === 'integer'
   543→            ? Empresa::select('id', 'empresa_id', 'nombre_comercial', 'razon_social', 'activo')->find($empresa)
   544→            : $empresa;
   545→        $condicion_request_tiene_en = $request->has('en') && filter_var($request->en, FILTER_VALIDATE_BOOLEAN) && $request->filled('campo')
   546→            && $request->filled('valores');
   547→        $campos_usuario = ['id', 'nombres', 'apellidos', 'documento', 'email', 'email_secundario', 'indicativo_telefono', 'telefono', 'codigo_iso2_pais_telefono', 'indicativo_telefono_secundario', 'telefono_secundario', 'codigo_iso2_pais_telefono_secundario', 'fecha_nacimiento', 'estado_id',
   548→            'ciudad_id', 'cargo_id', 'created_at'];
   549→        $con_relaciones     = $request->has('con_relaciones') && filter_var($request->con_relaciones, FILTER_VALIDATE_BOOLEAN);
   550→        $validar_relaciones = $request->has('validar_relaciones') && filter_var($request->validar_relaciones, FILTER_VALIDATE_BOOLEAN);
   551→        $solo_rol_mas_alto  = $request->has('solo_rol_mas_alto') && filter_var($request->solo_rol_mas_alto, FILTER_VALIDATE_BOOLEAN);
   552→
   553→        $relaciones_usuario = [
   554→            'cargo:id,nombre',
   555→            'estado:id,nombre',
   556→            'ciudad:id,departamento_id,nombre',
   557→            'ciudad.departamento:id,pais_id,nombre',
   558→            'ciudad.departamento.pais:id,nombre',
   559→            'empresasUsuarios:id,empresa_id,usuario_id,rol_id',
   560→            'empresasUsuarios.rol:id,name,guard_name,type',
   561→            'empresasUsuarios.empresa:id,empresa_id,nombre_comercial',
   562→            'ultimaSesion:id,usuario_id,created_at,updated_at'
   563→        ];
   564→
   565→        $relaciones_a_validar = [
   566→            'agendas as tiene_agendas',
   567→            'ofertasLaborales as tiene_ofertas_laborales',
   568→            'procesos as tiene_procesos',
   569→            'etapaUsuario as tiene_etapa_usuario'
   570→        ];
   571→
   572→        $datos_roles = [
   573→            'con_rol_tipo_empresa'      => $request->has('con_rol_tipo_empresa') && filter_var($request->con_rol_tipo_empresa, FILTER_VALIDATE_BOOLEAN),
   574→            'con_rol_tipo_superadmin'   => $request->has('con_rol_tipo_superadmin') && filter_var($request->con_rol_tipo_superadmin, FILTER_VALIDATE_BOOLEAN),
   575→            'ids_roles_tipo_empresa'    => [4, 6, 7, 8],
   576→            'ids_roles_tipo_superadmin' => [1, 2, 3, 5]
   577→        ];
   578→
   579→        if (!filter_var($empresa->activo, FILTER_VALIDATE_BOOLEAN)) {
   580→            return null;
   581→        }
   582→
   583→        $empresa_ids = [];
   584→
   585→        if ($empresa->empresa_id) {
   586→            $empresa_ids = [$empresa->id];
   587→        } else {
   588→            $sucursales    = $empresa->sucursales()->select('id', 'empresa_id')->where('activo', 1)->get()->toArray();
   589→            $empresa_ids   = array_column($sucursales, 'id');
   590→            $empresa_ids[] = $empresa->id;
   591→        }
   592→
   593→        $consulta = $this->modelo->select($campos_usuario)
   594→            ->whereHas('empresasUsuarios', function ($consulta) use ($empresa_ids, $datos_roles) {
   595→                $consulta->whereIn('empresas_usuarios.empresa_id', $empresa_ids)
   596→                    ->when($datos_roles['con_rol_tipo_empresa'], function ($consulta) use ($datos_roles) {
   597→                        $consulta->whereIn('empresas_usuarios.rol_id', $datos_roles['ids_roles_tipo_empresa']);
   598→                    })
   599→                    ->when($datos_roles['con_rol_tipo_superadmin'], function ($consulta) use ($datos_roles) {
   600→                        $consulta->whereIn('empresas_usuarios.rol_id', $datos_roles['ids_roles_tipo_superadmin']);
   601→                    });
   602→            })
   603→            ->when($con_relaciones, function ($consulta_relaciones) use ($relaciones_usuario) {
   604→                $consulta_relaciones->with($relaciones_usuario);
   605→            })
   606→            ->when($validar_relaciones, function ($consulta) use ($relaciones_a_validar) {
   607→                $consulta->withExists($relaciones_a_validar);
   608→            })
   609→            ->when($condicion_request_tiene_en, function ($consulta_en) use ($request) {
   610→                $consulta_en->whereIn($request->campo, $request->valores);
   611→            });
   612→
   613→        if (isset($request->estado_id)) {
   614→            $consulta->where('estado_id', $request->estado_id);
   615→        }
   616→
   617→        $usuarios = $consulta->get();
   618→
   619→        if ($con_relaciones && $solo_rol_mas_alto) {
   620→            $usuarios->transform(function ($usuario) use ($empresa_ids) {
   621→                if (!isset($usuario->empresasUsuarios)) {
   622→                    return $usuario;
   623→                }
   624→
   625→                $relaciones_filtradas = $usuario->empresasUsuarios
   626→                    ->filter(function ($rel) use ($empresa_ids) {
   627→                        return in_array($rel->empresa_id, $empresa_ids, true) && ((int) $rel->rol_id !== 9);
   628→                    })
   629→                    ->sortBy('rol_id');
   630→
   631→                $primera = $relaciones_filtradas->first();
   632→                $usuario->setRelation('empresasUsuarios', $primera ? collect([$primera]) : collect());
   633→                return $usuario;
   634→            });
   635→        }
   636→
   637→        return $usuarios;
   638→    }
