   651→    public function obtenerPorProceso(int $id, Request $request): Collection {
   652→        return $this->modelo::select('id', 'empresa_usuario_id', 'area_id', 'cargo_id', 'tipo_documento_id', 'genero_id', 'ciudad_id', 'estado_id', 'nombres', 'apellidos', 'documento', 'email', 'email_secundario', 'fecha_nacimiento', 'direccion', 'indicativo_telefono', 'telefono', 'codigo_iso2_pais_telefono', 'indicativo_telefono_secundario', 'telefono_secundario', 'codigo_iso2_pais_telefono_secundario', 'profesion', 'created_at')
   653→            ->with([
   654→                'ciudad:id,departamento_id,nombre',
   655→                'ciudad.departamento:id,pais_id,nombre',
   656→                'ciudad.departamento.pais:id,nombre',
   657→                'tipoDocumento:id,nombre,abreviatura',
   658→                'datoAdicional:id,usuario_id,area_estudio_id,estado_academico',
   659→                'datoAdicional.areaEstudio:id,nombre',
   660→                'agendas' => function ($agendas) use ($id, $request) {
   661→                    $relaciones = [
   662→                        'prueba:id,nombre,slug',
   663→                        'perfil:id,nombre',
   664→                        'estado:id,nombre'
   665→                    ];
   666→
   667→                    if (!empty($request->incluir_procesos_pruebas) && filter_var($request->incluir_procesos_pruebas, FILTER_VALIDATE_BOOLEAN)) {
   668→                        $relaciones['prueba.procesosPruebas'] = function ($consulta_procesos_pruebas) use ($id) {
   669→                            $consulta_procesos_pruebas->select('id', 'prueba_id', 'perfil_id', 'proceso_id', 'porcentaje', 'created_at', 'updated_at')
   670→                                ->where('proceso_id', $id)
   671→                                ->with('perfil:id,nombre');
   672→                        };
   673→                    }
   674→
   675→                    $agendas->select('id', 'proceso_id', 'prueba_id', 'evaluado_id', 'estado_id', 'fecha_inicio', 'fecha_cierre', 'fecha_procesamiento', 'perfil_id', 'ajuste')
   676→                        ->with($relaciones)
   677→                        ->where('proceso_id', $id)
   678→                        ->whereHas('prueba', function ($consulta_prueba) use ($id) {
   679→                            $consulta_prueba->whereHas('procesosPruebas', function ($consulta_procesos_pruebas) use ($id) {
   680→                                $consulta_procesos_pruebas->where('proceso_id', $id);
   681→                            });
   682→                        });
   683→                }
   684→            ])
   685→            ->whereHas('agendas', function ($consulta) use ($id, $request) {
   686→                $consulta->where('proceso_id', $id);
   687→
   688→                $consulta->whereHas('prueba', function ($consulta_prueba) use ($id) {
   689→                    $consulta_prueba->whereHas('procesosPruebas', function ($consulta_procesos_pruebas) use ($id) {
   690→                        $consulta_procesos_pruebas->where('proceso_id', $id);
   691→                    });
   692→                });
   693→
   694→                if ($request->filled('estado_agenda_id')) {
   695→                    $consulta->where('estado_id', $request->estado_agenda_id);
   696→                }
   697→
   698→                if ($request->filled('fecha_inicio_desde')) {
   699→                    if ($request->filled('fecha_inicio_hasta')) {
   700→                        $consulta->whereBetween('fecha_inicio', [$request->fecha_inicio_desde, $request->fecha_inicio_hasta]);
   701→                    } else {
   702→                        $consulta->where('fecha_inicio', '>=', $request->fecha_inicio_desde);
   703→                    }
   704→                }
   705→
   706→                if ($request->filled('fecha_procesamiento_desde')) {
   707→                    if ($request->filled('fecha_procesamiento_hasta')) {
   708→                        $consulta->whereBetween('fecha_procesamiento', [$request->fecha_procesamiento_desde, $request->fecha_procesamiento_hasta]);
   709→                    } else {
   710→                        $consulta->where('fecha_procesamiento', '>=', $request->fecha_procesamiento_desde);
   711→                    }
   712→                }
   713→            })
   714→            ->when($request->filled('nombre'), function ($consulta) use ($request) {
   715→                $consulta->whereRaw("CONCAT(nombres, ' ', apellidos) LIKE '%" . $request->nombre . "%'");
   716→            })
   717→            ->when(
   718→                $request->has('en') && filter_var($request->en, FILTER_VALIDATE_BOOLEAN) && $request->filled('campo') && $request->filled('valores'),
   719→                fn($consulta) => $consulta->whereIn($request->campo, $request->valores)
   720→            )
   721→            ->when($request->filled('documento'), fn($consulta) => $consulta->where('documento', $request->documento))
   722→            ->when($request->filled('email'), fn($consulta) => $consulta->where('email', $request->email))
   723→            ->when($request->filled('indice_talento_nivel'), function ($consulta) use ($request, $id) {
   724→                $consulta->whereRaw("
   725→                    CASE
   726→                        WHEN ? = 'alto' THEN fn_indice_talento(?, users.id) BETWEEN 71 AND 100
   727→                        WHEN ? = 'medio' THEN fn_indice_talento(?, users.id) BETWEEN 41 AND 70
   728→                        WHEN ? = 'bajo' THEN fn_indice_talento(?, users.id) BETWEEN 10 AND 40
   729→                        ELSE 1 = 1
   730→                    END
   731→                ", [
   732→                    $request->indice_talento_nivel, $id,
   733→                    $request->indice_talento_nivel, $id,
   734→                    $request->indice_talento_nivel, $id
   735→                ]);
   736→            })
   737→            ->when($request->filled('recientes'), function ($consulta) use ($request) {
   738→                $orden = match($request->recientes) {
   739→                    '1' => 'DESC',
   740→                    '0' => 'ASC'
   741→                };
   742→
   743→                $consulta->orderBy('created_at', $orden);
   744→            }, fn($consulta) => $consulta->orderBy('created_at', 'DESC'))
   745→            ->get();
   746→    }
