$indice_talento       = null;
$estado_recomendacion = null;
$recomendacion        = 0;

$proceso = $this->proceso_repositorio->getUnoAvanzado(new Request(['vacante_id' => $vacante_id]));
if ($proceso) {
    $proceso->load('pruebasAsociadas');
    $pruebas_ids     = $proceso->pruebasAsociadas->pluck('prueba_id')->toArray();
    $es_iq_factorial = in_array(Prueba::IQ_FACTORIAL_ID, $pruebas_ids);

    $resultado_indice = $this->proceso_repositorio->obtenerIndiceTalento($proceso->id, $usuario_id);
    $valor_indice     = $resultado_indice?->indice_talento;
    $indice_talento   = $valor_indice;

    if (is_null($valor_indice)) {
        $estado_recomendacion = null;
        $recomendacion        = 0;
    } elseif ($valor_indice == -2) {
        $estado_recomendacion = 'Pruebas pendientes';
        $recomendacion        = 0;
    } elseif ($valor_indice == -1) {
        $estado_recomendacion = 'Procesamiento pendiente';
        $recomendacion        = 0;
    } elseif ($es_iq_factorial) {
        if ($valor_indice <= EtapaVacanteUsuario::CALIFICACION_BAJA_IQ) {
            $estado_recomendacion = 'No recomendado';
            $recomendacion        = 1;
        } elseif ($valor_indice <= EtapaVacanteUsuario::CALIFICACION_MEDIA_IQ) {
            $estado_recomendacion = 'Recomendado con sugerencias';
            $recomendacion        = 2;
        } else {
            $estado_recomendacion = 'Recomendado';
            $recomendacion        = 3;
        }
    } else {
        if ($valor_indice <= EtapaVacanteUsuario::CALIFICACION_BAJA_PSICOMETRICA) {
            $estado_recomendacion = 'No recomendado';
            $recomendacion        = 1;
        } elseif ($valor_indice <= EtapaVacanteUsuario::CALIFICACION_MEDIA_PSICOMETRICA) {
            $estado_recomendacion = 'Recomendado con sugerencias';
            $recomendacion        = 2;
        } else {
            $estado_recomendacion = 'Recomendado';
            $recomendacion        = 3;
        }
    }
}

