 */
(function() {
    const APLICAR_FILTROS_ETAPAS = window.aplicarFiltrosDropdown;

    // Sobrescribir con función que maneja ambas tablas
    window.aplicarFiltrosDropdown = function(input_id, filtros) {
        // Si el filtro pertenece a la tabla de resultados
        if (input_id === `filtro_${nombre_tabla_resultados}`) {
            window[nombre_tabla_resultados + '_filtros'] = filtros;
            actualizarDatatables(nombre_tabla_resultados);
        } else if (typeof APLICAR_FILTROS_ETAPAS === 'function') {
            APLICAR_FILTROS_ETAPAS(input_id, filtros);
        }
    };
})();

$(document).ready(function() {
    moment.locale('es');
    $(document).on('click', '#resultados-pestana', function() {
        if ($.fn.DataTable.isDataTable(`#${nombre_tabla_resultados}`)) {
            actualizarDatatables(nombre_tabla_resultados);
        }
    });

    $('.checkbox-container').on('click mousedown', function(evento) {
