        $('#input-archivos').trigger('click');
    });

    $(document).on('click', '#btn-comparativo-basico', function() {
        comparativoBasico();
    });

    $(document).on('click', '#btn-identificar-mejores', function() {
        identificarMejoresCandidatos();
    });

    /**
     * Actualizar el texto del botón de exportar según las etapas seleccionadas.
     * Si hay etapas marcadas muestra "Exportar selección", de lo contrario "Exportar todo".
     *
     * @returns {void}
     * @author Andrés Morales
     */
    function actualizarTextoBotonExportar() {
        const ETAPAS_MARCADAS = CAJAS_IDS.filter(id => $(id).is(':checked')).length;
        const BOTON = $('#btn-exportar-resultados');

        if (ETAPAS_MARCADAS > 0) {
            BOTON.html(' Exportar selección');
        } else {
            BOTON.html(' Exportar todo');
        }
    }

    CAJAS_IDS.forEach(id => {
        $(id).on('change', actualizarTextoBotonExportar);
    });

    $(document).on('change', `#filtro_mas_recientes_${nombre_tabla_resultados}`, function() {
        actualizarDatatables(nombre_tabla_resultados);
    });

    $(document).on('click', '.copiar-elemento',function () {
        let texto = $(this).data('texto');
        navigator.clipboard.writeText(texto).then(function() {
