/**
 * Mostrar el resultado de la video entrevista.
 *
 * @param {Object} etapa Objeto etapa con preguntas, puntajes y comentarios.
 * @returns {string} HTML del resultado de la video entrevista.
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function mostrarResultadoVideoentrevista(etapa) {
    let preguntas = etapa.preguntas || [];
    let contenido_preguntas = '';
    let transcripcion = etapa?.transcripcion?.texto;
    if (transcripcion != null) {
        let expresion_regular = /Pregunta\s+(\d+)\s+([\s\S]*?)\s+Respuesta\s+([\s\S]*?)(?=Pregunta\s+\d+|$)/g;
        let encontrado;
        let resultados = [];
        while ((encontrado = expresion_regular.exec(transcripcion)) !== null) {
            resultados.push({
                numero_pregunta: Number(encontrado[1]),
                pregunta: encontrado[2].trim(),
                respuesta: encontrado[3].trim()
            });
        }
        $.each(resultados, function(indice, pregunta) {
            contenido_preguntas += `
                <div class="row">
                    <div class="col-12 text-headline-6 text-gray-10 mb-2">
                        Pregunta ${indice + 1}
                    </div>
                    <div class="col-12 text-body-3 text-gray-30 mb-3">${pregunta?.pregunta}</div>
                </div>
                <div class="row mt-3 respuestas">
                    <div class="col-12 text-body-2 text-gray-10 mb-2">Respuesta</div>
                    <div class="col-12 text-body-3 text-gray-30 mb-3">
                        ${pregunta?.respuesta || ''}
                    </div>
                </div>
            `;
        });
    } else {
        $.each(preguntas, function(indice, pregunta) {
            contenido_preguntas += `
                <div class="row">
                    <div class="col-12 text-body-2 text-gray-10 mb-2">
                        Pregunta ${indice + 1}
                    </div>
                    <div class="col-12 text-body-3 text-gray-30 mb-3">${pregunta.enunciado}</div>
                </div>
                <div class="row mt-3 respuestas">
                    <div class="col-12 text-body-2 text-gray-10 mb-2">Respuesta</div>
                    <div class="col-12 text-body-3 text-gray-30 mb-3">
                        ${pregunta?.respuestas[0]?.respuesta || ''}
                    </div>
                </div>
            `;
        });
    }
    let videos = [];
    preguntas.forEach(pregunta => {
        pregunta.respuestas.forEach(respuesta => {
            respuesta.archivos.forEach(archivo => {
                videos.push(archivo);
            });
        });
    });
    if (etapa?.puntaje == null && etapa?.puntaje_ia == null && videos.length == 0) {
        return `
            <div class="col-12">
                <div class="row justify-content-center my-14">
                    <div class="col-auto">
                        <i class="bi bi-youtube text-gray-60 icono-sin-completar-etapa"></i>
                    </div>
                    <div class="col-12 text-center text-headline-5">
                        Este candidato aún no ha completado la video entrevista
                    </div>
                </div>
            </div>
        `;
    } else {
        return `
            <div class="col-12 pregunta rounded-3 border px-4 pt-4 mb-4">
                <div class="row">
                    <div class="col-12 text-body-2 text-gray-10 mb-2 d-flex align-items-center gap-3">
                        Videograbación
                        <button class="btn btn-sm btn-outline-warning d-none btn-reprocesar-videoentrevista" onclick="reprocesarVideoentrevista(${etapa.id})">
                            <i class="bi bi-arrow-clockwise"></i> Reprocesar IA
                        </button>
                    </div>
                    <div class="col-12 text-body-3 text-gray-30 mb-3">
                        <div class="row" id="videos">
                            <div class="col-12 col-lg-9">
                                <div class="w-100 text-label-1 fw-semibold text-gray-10"></div>
                                <video class="w-100 rounded-3 pointer" id="reproductor-videoentrevista" src="/archivos-abrir/${videos[0]?videos[0].id : ''}" controls>
                                    <source type="video/mp4">
                                </video>
                            </div>
                            <div class="col-12 overflow-auto col-lg-3" id="contenedor-lista-videos">
                                <div class="row" id="lista-videos">
                                    ${videos.length > 0 ? videos.map((video, i) => `
                                        <div class="w-100 text-label-1 fw-semibold text-gray-10 mb-3 pointer" onclick="reproducirVideoEntrevista(${video.id}, ${i + 1});">
                                            Pregunta ${i + 1}:
                                            <video class="w-100 rounded-3 pointer">
                                                <source src="/archivos-abrir/${video.id}" type="video/mp4">
                                                Tu navegador no soporta el elemento de video.
                                            </video>
                                        </div>
                                    `).join('') : ``}
                                </div>
                            </div>
                        </div>
                        <div class="row justify-content-center d-none" id="sin-videos">
                            <div class="col-3 bg-white rounded-3 border text-center py-14">
                                <i class="bi bi-camera-video-off-fill text-gray-70 my-14" style="font-size: 70px"></i>
                            </div>
                            <div class="col-12 text-label-1 text-center fw-semibold text-gray-10 mt-2">
                                No hemos encontrado videos
                            </div>
                            <div class="col-12 text-label-1 text-center fw-semibold mt-2">
                                Tus videos han expirado luego de 90 días o han sido eliminados. <a href="/" class="text-blue-40">Más información</a>
                            </div>
                        </div>
                    </div>
                    ${etapa.formato_entrevista ? `
                        <div class="col-12 text-body-3 text-gray-30 mb-3">
                            <div class="row justify-content-end">
                                <div class="col-auto">
                                    ${crearBoton({
                                        clases: `btn-outline-primary`,
                                        texto: '<i class="bi bi-eye pe-3"></i> Ver formato de entrevista',
                                        onclick: `verFormatoEntrevista(${etapa.id})`
                                    })}
                                </div>
                            </div>
                        </div>
                    ` : ''}
                    <div class="col-12 text-body-3 text-gray-30 mb-3">${contenido_preguntas}</div>
                </div>
            </div>
            <div class="col-12 mb-4">
                <div class="w-100 border-top"></div>
            </div>
            <div class="col-12 text-body-2 text-gray-10 mb-2">
                Notas de IA
            </div>
            <div class="col-12 text-body-3 text-gray-30 mb-3">
                ${etapa.notas_ia || ''}
            </div>
            <div class="col-12" id="seccion-comentarios-videoentrevista">
                ${mostrarSeccionComentarios(etapa.comentarios, 'videoentrevista')}
            </div>
            <div class="my-4">
                <div class="col-12 my-3 text-body-2 text-gray-10">
                    Adicionales
                </div>
                <div class="col-12">
                    <div class="row">
                        <div class="col">
                            ${crearEditorTexto({
                                id: 'comentario_videoentrevista',
                                name: 'comentario_videoentrevista',
                                input_container_class: 'mb-0',
                                class: 'classic-editor-opciones',
                                disabled: false,
                                required: false,
                                label: '',
                            })}
                        </div>
                        <div class="col-auto d-flex align-items-end">
                            ${crearBoton({
                                clases: `btn-primary btn-circle`,
                                texto: '<i class="bi bi-send-fill"></i>',
                                onclick: `enviarComentario(${etapa.id}, 'videoentrevista')`
                            })}
                        </div>
                    </div>
                </div>
                <div class="col-12 mt-10 text-body-2 text-gray-10">
                    <div class="row justify-content-between">
                        <div class="col-6">
                            <div class="row align-items-center">
                                <div class="col-auto text-label-1">
                                    Puntuación dada por IA
                                </div>
                                <div class="col-auto pe-0 py-2">
                                    ${crearAlerta(`${etapa.puntaje_ia && etapa.puntaje_ia > 59 ? 'success' : 'danger'}`, `${etapa.puntaje_ia || 0}%`, 'py-2 px-3')}
                                </div>
                            </div>
                        </div>
                        <div class="col-6">
                            <div class="row justify-content-end align-items-center">
                                <div class="col-8 text-label-1">
                                    Puntuación dada por reclutador
                                </div>
                                <div class="col-4">
                                    ${crearInput({
                                        autocomplete: 'off',
                                        id: 'puntaje_videoentrevista',
                                        input_container_class: 'mb-0',
                                        maxlength: 8,
                                        label: 'Ej 100%',
                                        onblur: `actualizarPuntajePruebaTecnica(${etapa.id}, this.value)`,
                                        value: etapa.puntaje || '',
                                        disabled: etapa.puntaje == null && detalle_usuario?.etapa_actual?.etapa?.nombre == etapa.nombre_etapa ? false : true
                                    })}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        `;
    }
}

