                                    ? crearBoton({
                                        clases: 'btn-text-danger btn-circle p-2',
                                        texto: '<i class="bi bi-trash text-headline-5"></i>',
                                        tooltip: crearTooltip({
                                            placement: `top`,
                                            content: `Eliminar agenda`,
