/**
 * Mostrar resultado de consulta de antecedentes del candidato.
 *
 * @param {Object} etapa Datos de la etapa.
 * @returns {string} HTML del contenedor para cargar los resultados.
 * @author Andres González
 */
function mostrarResultadoAntecedentes(etapa) {
    const CONTENEDOR_ID = 'contenedor-antecedentes-resultado';

    setTimeout(() => {
        if (!detalle_usuario || !detalle_usuario.documento) {
            $(`#${CONTENEDOR_ID}`).html(estadoVacioAntecedentes());
            return;
        }

        $.ajax({
            url: `/antecedentes-documento/${detalle_usuario.documento}`,
            type: 'GET',
            dataType: 'json',
            success: function(respuesta) {
                if (respuesta.data && (!Array.isArray(respuesta.data) || respuesta.data.length > 0)) {
                    let datos = Array.isArray(respuesta.data) ? respuesta.data[0] : respuesta.data;
                    let fecha_consulta = datos.created_at ? moment(datos.created_at).format('DD/MM/YYYY HH:mm') : 'N/A';
                    let fecha_expedicion = datos.fecha_expedicion ? moment(datos.fecha_expedicion).format('DD/MM/YYYY') : 'N/A';
                    let genero = datos.genero ? datos.genero.nombre : 'N/A';

                    $(`#${CONTENEDOR_ID}`).html(`
                        <div class="row">
                            <div class="col-12">
                                <div class="card">
                                    <div class="card-body">
                                        <div class="d-flex justify-content-between align-items-center mb-4">
                                            <h5 class="card-title mb-0">
                                                <i class="bi bi-shield-check me-2"></i>Información de Antecedentes
                                            </h5>
                                            ${datos.resultado_id ? crearBoton({
                                                clases: 'btn-primary',
                                                texto: '<i class="bi bi-download me-2"></i>Descargar',
                                                onclick: `descargarReporteAntecedentes('${datos.resultado_id}', '${datos.documento}')`
                                            }) : ''}
                                        </div>
                                        <div class="row g-3">
                                            <div class="col-12 col-md-6">
                                                <strong>Nombre:</strong> ${datos.nombre || 'N/A'}
                                            </div>
                                            <div class="col-12 col-md-6">
                                                <strong>Tipo de documento:</strong> ${datos.tipo_documento || 'N/A'}
                                            </div>
                                            <div class="col-12 col-md-6">
                                                <strong>Documento:</strong> ${datos.documento || 'N/A'}
                                            </div>
                                            <div class="col-12 col-md-6">
                                                <strong>Fecha de expedición:</strong> ${fecha_expedicion}
                                            </div>
                                            <div class="col-12 col-md-6">
                                                <strong>Género:</strong> ${genero}
                                            </div>
                                            <div class="col-12 col-md-6">
                                                <strong>Nivel de riesgo:</strong> ${datos.nivel_riesgo || 'N/A'}
                                            </div>
                                            <div class="col-12 col-md-6">
                                                <strong>Estado:</strong> ${datos.estado || 'N/A'}
                                            </div>
                                            <div class="col-12 col-md-6">
                                                <strong>Fecha de consulta:</strong> ${fecha_consulta}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    `);
                } else {
                    $(`#${CONTENEDOR_ID}`).html(estadoVacioAntecedentes());
                }
            },
            error: function() {
                $(`#${CONTENEDOR_ID}`).html(estadoVacioAntecedentes());
            }
        });
    }, 100);

    return `<div id="${CONTENEDOR_ID}" class="col-12"></div>`;
}

/**
 * Descargar reporte PDF de antecedentes.
 *
 * @param {string} resultado_id ID del resultado en TusDatos.
 * @param {string} documento Número de documento del candidato.
 * @returns {void}
 * @author Andres González
 */
function descargarReporteAntecedentes(resultado_id, documento) {
    Swal.fire({
        title: 'Descargando reporte...',
        html: '<p>Por favor espera mientras se descarga el reporte de antecedentes</p>',
        allowOutsideClick: false,
        showConfirmButton: false,
        didOpen: () => Swal.showLoading()
    });

    $.ajax({
        url: '/antecedentes-descargar-pdf',
        type: 'POST',
        data: {
            resultado_id: resultado_id,
            documento: documento,
            _token: $('meta[name="csrf-token"]').attr('content')
        },
        xhrFields: {
            responseType: 'blob'
        },
        success: function(blob, estado, respuesta_http) {
            const TIPO_CONTENIDO = respuesta_http.getResponseHeader('content-type');

            if (TIPO_CONTENIDO && TIPO_CONTENIDO.indexOf('application/json') !== -1) {
                Swal.close();
                mostrarToast('danger', 'Ocurrió un error al descargar el reporte de antecedentes');
            } else {
                const ENLACE_BLOB = window.URL.createObjectURL(blob);
                const ENLACE = document.createElement('a');
                ENLACE.href = ENLACE_BLOB;
                ENLACE.download = `antecedentes_${documento}.pdf`;
                document.body.appendChild(ENLACE);
                ENLACE.click();
                document.body.removeChild(ENLACE);
                window.URL.revokeObjectURL(ENLACE_BLOB);
                Swal.close();
            }
        },
        error: function(respuesta_http) {
            Swal.close();
            mostrarToast('danger', 'Ocurrió un error al descargar el reporte de antecedentes');
        }
    });
}

