                                    <div class="col-12 text-body-3">${pregunta}</div>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div class="row mb-5">
                        <div class="col pe-0">
                            <div class="col-12 px-4 pt-4 bg-white rounded-4 shadow-1">
                                <div class="row">
                                    <div class="col-12 text-label-2 text-gray-10">IA</div>
                                    <div class="col-12 text-body-3 pb-2">${respuesta_comentario}</div>
                                </div>
                            </div>
                        </div>
                        <div class="col-auto">
                            <img src="/iconos/icono_ia.svg" class="rounded-circle bg-state-yellow border p-1" width="50" height="50">
                        </div>
                    </div>
                `);
                let comentarios_ia = $('#contenedor-comentarios-comparacion-ia').children('.comentario-ia').length;
                $('#comentarios-ia').removeClass('d-none').text(comentarios_ia);
                $('#contenedor-comentarios-comparacion-ia').removeClass('d-none');
                establecerDatosClassicEditor('comentario_comparacion', '');
                $('#modal-generando-ia').modal('hide');
                $('#modal-respuesta-candidatos-ia').removeClass('d-none');
            },
            error: function (error) {
                mostrarToast('danger', 'Error al generar datos con IA.');
                $('#modal-respuesta-candidatos-ia').removeClass('d-none');
            }
        });
    } else {
        mostrarToast('danger', 'Seleccione al menos 2 candidatos para comparar con la IA.');
    }
}

/**
 * Descargar reporte PDF con respuesta de IA sobre candidatos recomendados.
 * Abre el PDF en una nueva ventana (similar a comparativoBasico).
 *
 * @returns {void}
 * @author Andrés Morales
 */
function descargarRespuestaCandidatosIA() {
    // Validar que existe la respuesta de IA
    if (!respuesta_ia_candidatos_recomendados || !respuesta_ia_candidatos_recomendados.respuesta_ia) {
        mostrarToast('warning', 'No hay una respuesta de IA disponible para descargar.');
        return;
    }

    // Validar que existe la vacante
    if (!VACANTE_ID) {
        mostrarToast('danger', 'Error: No se pudo identificar la vacante.');
        return;
    }

    // Crear formulario para enviar POST y abrir PDF en nueva ventana
    var formulario = document.createElement('form');
    formulario.method = 'POST';
    formulario.action = '/vacantes-descargar-reporte-respuesta-ia';
    formulario.target = '_blank';

    // Agregar token CSRF
    var csrf_input = document.createElement('input');
    csrf_input.type = 'hidden';
    csrf_input.name = '_token';
    csrf_input.value = $('meta[name="csrf-token"]').attr('content');
    formulario.appendChild(csrf_input);

    // Agregar vacante_id
    var vacante_input = document.createElement('input');
    vacante_input.type = 'hidden';
    vacante_input.name = 'vacante_id';
    vacante_input.value = VACANTE_ID;
    formulario.appendChild(vacante_input);

    // Agregar respuesta_ia como JSON string
    var respuesta_input = document.createElement('input');
    respuesta_input.type = 'hidden';
    respuesta_input.name = 'respuesta_ia';
    respuesta_input.value = JSON.stringify(respuesta_ia_candidatos_recomendados.respuesta_ia);
    formulario.appendChild(respuesta_input);

    // Agregar formulario al body y enviarlo
    document.body.appendChild(formulario);
    formulario.submit();
    document.body.removeChild(formulario);

    mostrarToast('success', 'Generando reporte de candidatos con IA...');
}

/**
 * Ver detalle completo de un candidato con sus etapas y resultados.
 * Muestra un modal con información detallada del candidato y un acordeón de etapas.
 *
 * @param {number} usuario_id ID del usuario candidato.
 * @param {string|null} etapa_expandir Nombre de la etapa a expandir automáticamente.
 * @returns {void}
 * @author Jair Carvajal
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 * @author Esperanza Olivo
 */
function verDetalleCandidato(usuario_id, etapa_expandir = null) {
    usuario_detalle_id = usuario_id;
    $.ajax({
        url: `/vacantes-detalle-aplicante/${VACANTE_ID}/${usuario_id}`,
        type: 'GET',
        dataType: 'json',
        success: function(respuesta) {
            detalle_usuario = respuesta.data;
            let etapas = respuesta.data.etapas;
            window.etapas_candidato = etapas;

            etapas.push({
                nombre_etapa: 'Consulta de antecedentes',
                id: null,
                etapa_completada: false,
                puntaje: null,
                puntaje_ia: null
            });

            mostrarCardDetalleCandidato(respuesta.data);
            $('#acordeon-etapas-candidato').empty().append(crearAcordeon({
                id: 'acordeon',
                acordeon: etapas.map((etapa, indice) => ({
                    id: `etapa-${indice}`,
                    titulo: `${etapa.nombre_etapa}`,
                    contenido: mostrarResultadoEtapa(etapa),
                    adicional: `data-etapa_vacante_id="${etapa.id}" data-nombre_etapa="${etapa.nombre_etapa}"`,
                    seleccionar: true,
                    acordeon_header_class: 'py-6',
                    opciones_izquierda: `
                        <div class="col-auto ps-2 position-absolute z-3">
                            ${crearCheckbox({
                                id: 'checkbox',
                                name: 'checkbox',
                                class: 'checkbox-etapa',
                                required: true,
                                disabled: false,
                                onchange: `seleccionarCheckboxEtapa();`
                            })}
                        </div>
                    `,
                    opciones_derecha: `
                        <div class="col-auto end-0 me-10 ps-2 position-absolute z-3">
                            <div class="row align-items-center">
                                ${(() => {
                                    if (['Revisión HV', 'Preguntas prefiltro', 'Video entrevista', 'Entrevista'].includes(etapa.nombre_etapa)) {
                                        return '';
                                    }

                                    if (etapa.nombre_etapa === 'Documentos para contratación') {
                                        let tiene_archivos = etapa.archivos_solicitados?.archivos_guardados?.length > 0;
                                        if (!tiene_archivos) return '';
                                    } else {
                                        if (etapa.etapa_completada !== true) return '';
                                    }

                                    return `
                                        <div class="col-auto pe-0">
                                            ${crearBoton({
                                                clases: 'btn-outline-primary btn-circle btn-descargar-etapa',
                                                texto: '<i class="bi bi-download"></i>',
                                                adicional: 'data-etapa-indice="' + indice + '"'
                                            })}
                                        </div>
                                    `;
                                })()}
                                <div class="col-auto px-4" ${etapa.nombre_etapa === 'Documentos para contratación' ? `id="contenedor-cantidad-adjuntos"` : ''}>
                                    ${
                                    etapa.nombre_etapa === 'Documentos para contratación'
                                        ? crearTag({ texto: '', class: 'tag-tonal-blue cantidad-adjuntos' })
                                        : etapa.etapa_completada !== true
                                            ? crearTag({
                                                texto: `Resultados pendientes`,
                                                class: 'bg-gray-80 text-gray-30'
                                            })
                                            : (etapa.puntaje != null
                                                ? crearTag({
                                                    texto: `${etapa.puntaje}%`,
                                                    class: etapa.nombre_etapa === 'Pruebas psicométricas'
                                                        ? obtenerClaseEtiquetaSegunPuntajePsicometrica(etapa.puntaje)
                                                        : obtenerClaseEtiquetaSegunPuntajeObtenido(etapa.puntaje)
                                                })
                                                : (etapa.puntaje_ia != null
                                                    ? crearTag({
                                                        texto: `${etapa.puntaje_ia}%`,
                                                        class: etapa.nombre_etapa === 'Pruebas psicométricas'
                                                            ? obtenerClaseEtiquetaSegunPuntajePsicometrica(etapa.puntaje_ia)
                                                            : obtenerClaseEtiquetaSegunPuntajeObtenido(etapa.puntaje_ia)
                                                    })
                                                    : crearTag({
                                                        texto: `0%`,
                                                        class: etapa.nombre_etapa === 'Pruebas psicométricas'
                                                            ? obtenerClaseEtiquetaSegunPuntajePsicometrica(0)
                                                            : obtenerClaseEtiquetaSegunPuntajeObtenido(0)
                                                    })
                                                )
                                            )
                                    }
                                </div>
                            </div>
                        </div>
                    `
                }))
            }));
            $('#contenedor-hoja-vida-candidato').empty().append(mostrarDetalleHojaVida(respuesta.data));

            $('#btn-abrir-archivos').on('click', function (evento_click) {
                evento_click.preventDefault();
                $('#input-archivos').trigger('click');
            });
            $('#modal-detalle-resultados').modal('show');
            inicializarTooltips();
            mostrarPuntajeTotalPrefiltro();
            inicializarClassicEditor();
            $('.tooltip').remove();
            setTimeout(ajustarAlturaListaVideos, 100);

            // Expandir automáticamente la etapa indicada
            if (etapa_expandir) {
                setTimeout(function() {
                    expandirEtapaPorNombre(etapa_expandir);
                }, 30);
            }
        },
        error: function() {
            mostrarToast('danger', 'Error al cargar las etapas y candidatos');
        }
    });
}

/**
 * Expandir automáticamente una etapa del acordeón por su nombre.
 *
 * @param {string} nombre_etapa Nombre de la etapa a expandir.
 * @returns {void}
 * @author Andres Gonzalez
 */
function expandirEtapaPorNombre(nombre_etapa) {
    let item_etapa = $(`.accordion-item[data-nombre_etapa="${nombre_etapa}"]`);

    if (item_etapa.length > 0) {
        let boton = item_etapa.find('.accordion-button');

        if (boton.hasClass('collapsed')) {
            boton.trigger('click');
        }
    }
}

/**
 * Obtener la clase que corresponda para la etiqueta según el puntaje obtenido del aplicante.
 *
 * @param {number} puntaje Puntaje obtenido por el aplicante.
 * @returns {string}
 * @author Daniel Beltrán
 */
function obtenerClaseEtiquetaSegunPuntajeObtenido(puntaje) {
    let clase = 'tag-filled-smooth-red';

    if (puntaje > 70) {
        clase = 'tag-filled-green';
    } else if (puntaje >= 41 && puntaje <= 70) {
        clase = 'tag-filled-yellow';
    }

    return clase;
}

/**
 * Obtener la clase de la etiqueta según el puntaje obtenido para pruebas psicométricas.
 * Rangos: 0-59 rojo, 60-75 amarillo, 76-100 verde.
 *
 * @param {number} puntaje Puntaje obtenido por el aplicante.
 * @returns {string}
 * @author Sergio Vargas
 */
function obtenerClaseEtiquetaSegunPuntajePsicometrica(puntaje) {
    let clase = 'tag-filled-smooth-red';

    if (puntaje >= 76) {
        clase = 'tag-filled-green';
    } else if (puntaje >= 60 && puntaje <= 75) {
        clase = 'tag-filled-yellow';
    }

    return clase;
}

