                        </div>
                        <a class="col-auto" href="${url_archivo}" download>
                            <i class="bi bi-download text-blue-40 pointer"></i>
                        </a>
                    </div>
                </div>
            </div>
        `;
    });

    if (etapa?.archivos?.enlace != '' && etapa?.archivos?.enlace != null) {
        archivos_html += `
            <div class="col-auto archivo-item">
                <div class="col-auto px-3 border rounded-2">
                    <div class="row align-items-center">
                        <div class="col-auto py-3">
                            <i class="bi bi-link-45deg text-blue-40"></i>
                        </div>
                        <div class="col px-0 py-3 text-blue-40">
                            ${etapa.archivos.enlace}
                        </div>
                        <a class="col-auto" href="${etapa.archivos.enlace}" target="_blank">
                            <i class="bi bi-eye text-blue-40 pointer"></i>
                        </a>
                    </div>
                </div>
            </div>
        `;
    } else {
        archivos_html += `<div class="col-12 separador-invisible"></div>`;
