                    </div>
                    <div class="row g-3" id="contenedor-archivos-prueba-tecnica">${archivos_html}</div>
                    <div class="col-12 mt-5 mb-1 text-body-2 text-gray-10">
                        Comentario aplicante
                    </div>
                    <div class="col-12 text-body-3 text-gray-30">
