/**
 * Mostrar el detalle de la hoja de vida del candidato.
 *
 * @param {Object} candidato Objeto con la información del candidato.
 * @returns {string} HTML de las cards de hoja de vida.
 * @author Esperanza Olivo
 */
function mostrarDetalleHojaVida(candidato) {
    let perfil = candidato?.perfil_laboral_completo || {};
    let estudios = perfil?.estudios || [];
    let experiencias = perfil?.experiencias_laborales || [];
    let idiomas = perfil?.idiomas || [];
    let preferencias = perfil?.preferencia_laboral || {};
    let conocimientos = perfil?.conocimiento_disponibilidad || {};

    let estudios_ordenados = estudios.sort((actual, siguiente) => {
        let fecha_actual = actual.fecha_fin || actual.fecha_inicio || '';
        let fecha_siguiente = siguiente.fecha_fin || siguiente.fecha_inicio || '';
        return new Date(fecha_siguiente) - new Date(fecha_actual);
    });

    let experiencias_ordenadas = experiencias.sort((actual, siguiente) => {
        let fecha_actual = actual.fecha_fin || actual.fecha_inicio || '';
        let fecha_siguiente = siguiente.fecha_fin || siguiente.fecha_inicio || '';
        return new Date(fecha_siguiente) - new Date(fecha_actual);
    });

    let nivel_educativo_html = estudios_ordenados.length > 0 ? estudios_ordenados.map(estudio => `
        <div class="col-12 py-3 px-4 border rounded-3 mb-3">
            <div class="row">
                <div class="col">
                    <p class="mb-1 fw-bold text-gray-20">${estudio.titulo || ''}</p>
                    <p class="text-body-3 mb-1">
                        ${estudio.fecha_inicio || estudio.fecha_fin ? `<i class="bi bi-calendar4 text-headline-5 me-2"></i>` : ''}
                        ${estudio.fecha_inicio ? moment(estudio.fecha_inicio).format("MMM YYYY") : ''}
                        ${estudio.fecha_inicio && !estudio.fecha_fin ? ' - Actualmente' : (estudio.fecha_fin ? ` - ${moment(estudio.fecha_fin).format("MMM YYYY")}` : '')}
                    </p>
                    <p class="text-body-3 mb-1"><i class="bi bi-buildings text-headline-5 me-2"></i> ${estudio.institucion_educativa || ''}</p>
                    <p class="text-body-3 text-gray-10 mb-0">${estudio.nivel_educativo?.nombre || ''}</p>
                </div>
                <div class="col-auto">
                    ${estudio.fecha_fin 
                        ? crearTag({ texto: '<i class="bi bi-mortarboard me-1"></i> Graduado', class: 'tag-tonal-blue' })
                        : `<span class="text-body-3 text-gray-10">${estudio.jornada || ''}</span>`
                    }
                </div>
            </div>
        </div>
    `).join('') : '<p class="text-body-3 text-gray-30">No hay información de nivel educativo registrada.</p>';

    let experiencia_laboral_html = experiencias_ordenadas.length > 0 ? experiencias_ordenadas.map(experiencia => {
        let duracion = '';
        if (experiencia.fecha_inicio && experiencia.fecha_fin) {
            let fecha_inicio = moment(experiencia.fecha_inicio);
            let fecha_fin = moment(experiencia.fecha_fin);
            let fecha_anios = fecha_fin.diff(fecha_inicio, 'years');
            let fecha_meses = fecha_fin.diff(fecha_inicio.add(fecha_anios, 'years'), 'months');
            if (fecha_anios > 0) duracion += `${fecha_anios} año${fecha_anios > 1 ? 's' : ''}`;
            if (fecha_meses > 0) duracion += `${fecha_anios > 0 ? ' y ' : ''}${fecha_meses} mes${fecha_meses > 1 ? 'es' : ''}`;
        }

        return `
            <div class="col-12 py-3 px-4 border rounded-3 mb-3">
                <div class="row">
                    <div class="col">
                        <p class="mb-1 fw-bold text-gray-20">${experiencia.cargo || ''}</p>
                        <p class="text-body-3 mb-2">
                            ${experiencia.fecha_inicio || experiencia.fecha_fin ? `<i class="bi bi-calendar4 text-headline-5 me-2"></i>` : ''}
                            ${experiencia.fecha_inicio ? moment(experiencia.fecha_inicio).format("MMM YYYY") : ''}
                            ${experiencia.fecha_inicio ? (experiencia.fecha_fin ? ` - ${moment(experiencia.fecha_fin).format("MMM YYYY")}` : ' - Actualmente') : ''}
                            ${duracion ? ` | ${duracion}` : ''}
                        </p>
                        <p class="text-body-3 mb-1 fw-semibold text-gray-10">${experiencia.empresa || ''}</p>
                        ${experiencia.funciones ? `
                            <p class="text-body-2 fw-semibold text-gray-10 mt-3 mb-0">Funciones y responsabilidades</p>
                            <div class="w-100 text-body-3">${experiencia.funciones}</div>
                        ` : ''}
                    </div>
                </div>
            </div>
        `;
    }).join('') : '<p class="text-body-3 text-gray-30">No hay información de experiencia laboral registrada.</p>';

    let modalidad_trabajo = preferencias?.modalidades_trabajo?.map(modalidad => modalidad.nombre).join(', ') || preferencias?.modalidad_trabajo?.nombre || '';
    let salario_minimo = preferencias?.salario ? `$${Number(preferencias.salario).toLocaleString('es-CO')}` : '';
    let salario_maximo = preferencias?.salario_maximo ? `$${Number(preferencias.salario_maximo).toLocaleString('es-CO')}` : '';
    let rango_salario = salario_minimo && salario_maximo ? `${salario_minimo} a ${salario_maximo}` : (salario_minimo || salario_maximo || 'No especificado');

    let preferencias_html = `
        <div class="col-12">
            <div class="row mb-3">
                <div class="col-auto">
                    <i class="bi bi-house-door text-body-2 me-2"></i>
                    <span class="text-body-3 text-gray-10">Modalidad: ${modalidad_trabajo || 'No especificada'}</span>
                </div>
            </div>
            <div class="row">
                <div class="col-auto">
                    <i class="bi bi-currency-dollar text-body-2 me-2"></i>
                    <span class="text-body-3 text-gray-10">Salario: ${rango_salario}</span>
                </div>
            </div>
        </div>
    `;

    let habilidades = [];
    if (typeof perfil?.habilidades === 'string' && perfil.habilidades) {
        habilidades = perfil.habilidades.split(',').map(habilidad => habilidad.trim()).filter(habilidad => habilidad);
    } else if (Array.isArray(perfil?.habilidades)) {
        habilidades = perfil.habilidades;
    }

    let herramientas = [];
    if (typeof perfil?.herramientas_tecnologicas === 'string' && perfil.herramientas_tecnologicas) {
        herramientas = perfil.herramientas_tecnologicas.split(',').map(herramienta => herramienta.trim()).filter(herramienta => herramienta);
    } else if (Array.isArray(perfil?.herramientas_tecnologicas)) {
        herramientas = perfil.herramientas_tecnologicas;
    }

    let conocimientos_html = `
        <div class="col-12 mb-4">
            <div class="d-flex align-items-center gap-2 mb-2">
                <span class="text-body-2 fw-semibold text-gray-10">Habilidades</span>
                <i class="bi bi-info-circle text-gray-40" data-bs-toggle="tooltip" data-bs-title="Habilidades del candidato"></i>
            </div>
            <div class="d-flex flex-wrap gap-2">
                ${habilidades.length > 0 ? habilidades.map(habilidad => crearTag({ texto: habilidad, class: 'tag-tonal-gray rounded-pill' })).join('') : '<span class="text-body-3 text-gray-30">No especificadas</span>'}
            </div>
        </div>
        <div class="col-12">
            <div class="d-flex align-items-center gap-2 mb-2">
                <span class="text-body-2 fw-semibold text-gray-10">Herramientas</span>
                <i class="bi bi-info-circle text-gray-40" data-bs-toggle="tooltip" data-bs-title="Herramientas tecnológicas del candidato"></i>
            </div>
            <div class="d-flex flex-wrap gap-2">
                ${herramientas.length > 0 ? herramientas.map(herramienta => crearTag({ texto: herramienta, class: 'tag-tonal-gray rounded-pill' })).join('') : '<span class="text-body-3 text-gray-30">No especificadas</span>'}
            </div>
        </div>
    `;

    let idiomas_html = idiomas.length > 0 ? `
        <div class="col-12">
            <div class="d-flex flex-wrap gap-2">
                ${idiomas.map(idioma => crearTag({
                    texto: `${idioma.idioma?.nombre || ''}: ${idioma.nivel || ''}`,
                    class: 'tag-tonal-gray rounded-pill '
                })).join('')}
            </div>
        </div>
    ` : '<p class="text-body-3 text-gray-30">No hay idiomas registrados.</p>';

    let licencia_conducir = perfil?.licencia_conducir || conocimientos?.licencia_conducir;
    let tipo_licencia = perfil?.tipo_licencia_conducir || conocimientos?.tipo_licencia_conducir || '';
    let discapacidades = candidato?.discapacidades || [];

    let informacion_adicional_html = `
        <div class="col-12 mb-3">
            <div class="d-flex align-items-center">
                <i class="bi ${licencia_conducir ? 'bi-check-square' : 'bi-square'} text-body-2 me-2"></i>
                <span class="text-body-3 text-gray-10">Licencia de conducir${tipo_licencia ? ` : ${tipo_licencia}` : ''}</span>
            </div>
        </div>
        <div class="col-12">
            <div class="d-flex align-items-center">
                <img src="/iconos/icono_discapacidad.svg" alt="Icono Discapacidad" class="me-2">

                <span class="text-body-3 text-gray-10">
                    ${discapacidades.length === 0 ? 'Sin discapacidades' : discapacidades.map(discapacidad => discapacidad.nombre).join(', ')}
                </span>
            </div>
        </div>
    `;

    return `
        <div class="col-12 mt-4">
            <div class="card shadow-sm mb-4">
                <div class="card-body p-4">
                    <h6 class="text-body-1 fw-semibold text-gray-10 mb-4">Nivel educativo</h6>
                    <div class="row px-2">
                        ${nivel_educativo_html}
                    </div>
                </div>
            </div>
            <div class="card shadow-sm mb-4">
                <div class="card-body p-4">
                    <h6 class="text-body-1 fw-semibold text-gray-10 mb-4">Experiencia laboral</h6>
                    <div class="row px-2">
                        ${experiencia_laboral_html}
                    </div>
                </div>
            </div>
            <div class="card shadow-sm mb-4">
                <div class="card-body p-4">
                    <h6 class="text-body-1 fw-semibold text-gray-10 mb-4">Preferencias laborales</h6>
                    <div class="row px-2">
                        ${preferencias_html}
                    </div>
                </div>
            </div>
            <div class="card shadow-sm mb-4">
                <div class="card-body p-4">
                    <h6 class="text-body-1 fw-semibold text-gray-10 mb-4">Conocimientos requeridos</h6>
                    <div class="row px-2">
                        ${conocimientos_html}
                    </div>
                </div>
            </div>
            <div class="card shadow-sm mb-4">
                <div class="card-body p-4">
                    <h6 class="text-body-1 fw-semibold text-gray-10 mb-4">Idiomas</h6>
                    <div class="row px-2">
                        ${idiomas_html}
                    </div>
                </div>
            </div>
            <div class="card shadow-sm mb-4">
                <div class="card-body p-4">
                    <h6 class="text-body-1 fw-semibold text-gray-10 mb-4">Información adicional</h6>
                    <div class="row px-2">
                        ${informacion_adicional_html}
                    </div>
                </div>
            </div>
            <div class="col-12 mb-4" id="seccion-comentarios-hoja_vida">
                ${mostrarSeccionComentarios(candidato?.comentarios_hoja_vida || [], 'hoja_de_vida')}
            </div>
            <div class="col-12 mb-2 text-body-2 text-gray-10">
                Nuevo comentario
            </div>
            <div class="col-12 mb-4">
                <div class="row">
                    <div class="col">
                        ${crearEditorTexto({
                            id: 'comentario_hoja_vida',
                            name: 'comentario_hoja_vida',
                            input_container_class: 'mb-0 editor-comentario-pequeno',
                            class: 'classic-editor-opciones',
                            disabled: false,
                            required: false,
                            label: '',
                        })}
                    </div>
                    <div class="col-auto d-flex align-items-end">
                        ${crearBoton({
                            clases: 'btn-primary btn-circle',
                            texto: '<i class="bi bi-send-fill"></i>',
                            onclick: `enviarComentarioHojaVida()`
                        })}
                    </div>
                </div>
            </div>
        </div>
    `;
}

/**
 * Enviar un comentario en la sección de hoja de vida del candidato.
 *
 * @returns {void}
 * @author Esperanza Olivo
 */
function enviarComentarioHojaVida() {
    let comentario = obtenerDatosClassicEditor('comentario_hoja_vida');

    let comentario_limpio = comentario.replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim();
    if (comentario_limpio === '') {
        mostrarToast('warning', 'Debes escribir un comentario.');
        return;
    }
    establecerDatosClassicEditor('comentario_hoja_vida', '');
    $.ajax({
        url: `/comentarios`,
        type: 'POST',
        dataType: 'json',
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
            modelo_id: usuario_detalle_id,
            contenido: limpiarHTMLCKEditor(comentario),
        },
        success: function(respuesta) {
            mostrarToast('success', 'Comentario enviado correctamente.');
            $.ajax({
                url: `/comentarios`,
                type: 'GET',
                data: {
                    modelo_id: usuario_detalle_id,
                },
                dataType: 'json',
                success: function(datos) {
                    let comentarios = datos.data || [];
                    $(`#seccion-comentarios-hoja_vida`).empty().append(mostrarSeccionComentarios(comentarios, 'hoja_de_vida'));
                },
                error: function() {
                    mostrarToast('danger', 'Error al cargar los comentarios.');
                }
            });
        },
        error: function() {
            mostrarToast('danger', 'Error al enviar el comentario.');
        }
    });
}

/**
 * Muestra modal para consultar antecedentes de un candidato.
 *
 * @param {Object} datos Datos del candidato {id, nombre, email}.
 * @returns {void}
 * @author Andres González
 */
function modalConsultarAntecedentes(datos) {
    Swal.fire({
        showCloseButton: true,
        closeButtonHtml: '<i class="bi bi-x text-headline-4 text-gray-20"></i>',
        showConfirmButton: false,
        showDenyButton: false,
        showCancelButton: false,
        html: `
            <div class="row w-100 mx-0 mt-2">
                <div class="col-12 fw-semibold text-start text-gray-10 text-headline-4">
                    Consultar antecedentes
                </div>
                <div class="col-12 mt-4 text-start text-body-2 fw-normal text-gray-30">
                    Ingresa la información solicitada a continuación para consultar los antecedentes.
                </div>
                <div class="col-12 mt-4">
                    ${crearSelect2({
                        opciones: [
                            { nombre: '(CC) Cédula de Ciudadanía', id: 'CC' },
                            { nombre: '(CE) Cédula de Extranjería', id: 'CE' },
                            { nombre: '(INT) Documento Internacional', id: 'INT' },
                            { nombre: '(NIT) Número de Identificación Tributaria', id: 'NIT' },
                            { nombre: '(PP) Pasaporte', id: 'PP' },
                            { nombre: '(PPT) Permiso por Protección Temporal', id: 'PPT' },
                            { nombre: 'Nombre', id: 'NOMBRE' }
                        ],
                        id: 'tipo_documento_antecedente',
                        name: 'tipo_documento',
                        label: 'Tipo de documento',
                        required: true
                    })}
                </div>
                <div class="col-12 mt-4" id="contenedor_numero_documento_antecedente">
                    ${crearInput({
                        id: 'numero_documento_antecedente',
                        name: 'documento',
                        type: 'text',
                        label: 'Número de documento',
                        required: true,
                        maxlength: 50
                    })}
                </div>
                <div class="col-12 mt-4 d-none" id="contenedor_nombre_completo_antecedente">
                    ${crearInput({
                        id: 'nombre_completo_antecedente',
                        name: 'nombre',
                        type: 'text',
                        label: 'Nombre completo',
                        required: false,
                        maxlength: 255
                    })}
                </div>
                <div class="col-12 mt-4 d-none" id="contenedor_fecha_expedicion_antecedente">
                    ${crearInput({
                        id: 'fecha_expedicion_antecedente',
                        name: 'fecha_expedicion',
                        type: 'date',
                        label: 'Fecha de expedición',
                        required: false
                    })}
                </div>
                <div class="col-6 mt-5 mb-2">
                    ${crearBoton({
                        clases: 'btn-outline-primary w-100 justify-content-center',
                        texto: 'Cancelar',
                        onclick: `Swal.close();`
                    })}
                </div>
                <div class="col-6 mt-5 mb-2">
                    ${crearBoton({
                        clases: 'btn-primary w-100 justify-content-center',
                        texto: 'Consultar',
                        onclick: `Swal.getConfirmButton().click();`
                    })}
                </div>
            </div>
        `,
        focusConfirm: false,
        didOpen: () => {
            $('#tipo_documento_antecedente').on('change', function() {
                const TIPO = $(this).val();

                $('#contenedor_nombre_completo_antecedente').addClass('d-none');
                $('#contenedor_fecha_expedicion_antecedente').addClass('d-none');

                let texto_etiqueta = 'Número de documento';

                if (TIPO === 'CC' || TIPO === 'CE') {
                    $('#contenedor_fecha_expedicion_antecedente').removeClass('d-none');
                } else if (TIPO === 'INT' || TIPO === 'PP') {
                    $('#contenedor_nombre_completo_antecedente').removeClass('d-none');
                } else if (TIPO === 'NOMBRE') {
                    texto_etiqueta = 'Nombre completo';
                }

                $('#numero_documento_antecedente').siblings('label').text(texto_etiqueta);
            });

            $('#tipo_documento_antecedente').trigger('change');
        },
        preConfirm: () => {
            const TIPO_DOCUMENTO   = $('#tipo_documento_antecedente').val();
            const NUMERO_DOCUMENTO = $('#numero_documento_antecedente').val().trim();
            const NOMBRE_COMPLETO  = $('#nombre_completo_antecedente').val().trim();
            const FECHA_EXPEDICION = $('#fecha_expedicion_antecedente').val();

            if (!TIPO_DOCUMENTO) {
                mostrarToast('warning', 'Por favor selecciona el tipo de documento');
                return false;
            }

            if (!NUMERO_DOCUMENTO) {
                const TEXTO = TIPO_DOCUMENTO === 'NOMBRE' ? 'el nombre completo' : 'el número de documento';
                mostrarToast('warning', `Por favor ingresa ${TEXTO}`);
                return false;
            }

            if ((TIPO_DOCUMENTO === 'INT' || TIPO_DOCUMENTO === 'PP') && !NOMBRE_COMPLETO) {
                mostrarToast('warning', 'Por favor ingresa el nombre completo');
                return false;
            }

            const DATOS = {
                tipo_documento: TIPO_DOCUMENTO,
                documento: NUMERO_DOCUMENTO
            };

            if (TIPO_DOCUMENTO === 'INT' || TIPO_DOCUMENTO === 'PP') {
                DATOS.nombre = NOMBRE_COMPLETO;
            }

            if (FECHA_EXPEDICION) {
                DATOS.fecha_expedicion = FECHA_EXPEDICION;
            }

            return DATOS;
        }
    }).then((resultado) => {
        if (resultado.isConfirmed && resultado.value) {
            ejecutarConsultaAntecedentes(resultado.value);
        }
    });
}

/**
 * Ejecutar consulta de antecedentes.
 *
 * @param {Object} datos_consulta Datos de la consulta {tipo_documento, documento, fecha_expedicion}.
 * @returns {Promise<void>}
 * @author Andres González
 */
async function ejecutarConsultaAntecedentes(datos_consulta) {
    Swal.fire({
        title: 'Consultando antecedentes...',
        html: '<div class="spinner-border text-primary" role="status"></div><p class="mt-3">Por favor espera un momento</p>',
        allowOutsideClick: false,
        showConfirmButton: false
    });

    try {
        const DATOS_ENVIO = {
            _token:         $('input[name="_token"]').val(),
            tipo_documento: datos_consulta.tipo_documento,
            documento:      datos_consulta.documento
        };

        if (datos_consulta.nombre) {
            DATOS_ENVIO.nombre = datos_consulta.nombre;
        }

        if (datos_consulta.fecha_expedicion) {
            DATOS_ENVIO.fecha_expedicion = datos_consulta.fecha_expedicion;
        }

        if (datos_consulta.forzar) {
            DATOS_ENVIO.forzar = true;
        }

        if (detalle_usuario.id) {
            DATOS_ENVIO.aplicante_id = detalle_usuario.id;
        }

        const RESPUESTA = await $.ajax({
            url: '/antecedentes-consultar',
            type: 'POST',
            data: DATOS_ENVIO
        });

        Swal.close();

        const CODIGO = RESPUESTA.codigo || 200;

        if (CODIGO === 200 && RESPUESTA.existe) {
            Swal.fire({
                showCloseButton: true,
                closeButtonHtml: '<i class="bi bi-x text-headline-4 text-gray-20"></i>',
                showConfirmButton: false,
                showDenyButton: false,
                showCancelButton: false,
                html: `
                    <div class="row w-100 mx-0 mt-2">
                        <div class="col-12 fw-semibold text-start text-gray-10 text-headline-4">
                            Consulta existente
                        </div>
                        <div class="col-12 mt-4 text-start text-body-2 fw-normal text-gray-30">
                            ${RESPUESTA.message}
                        </div>
                        <div class="col-12 mt-3 text-start text-body-2 fw-normal text-gray-30">
                            ¿Deseas realizar una nueva consulta de todas formas?
                        </div>
                        <div class="col-6 mt-5 mb-2">
                            ${crearBoton({
                                clases: 'btn-outline-primary w-100 justify-content-center',
                                texto: 'No',
                                onclick: `Swal.close();`
                            })}
                        </div>
                        <div class="col-6 mt-5 mb-2">
                            ${crearBoton({
                                clases: 'btn-primary w-100 justify-content-center',
                                texto: 'Sí, consultar',
                                onclick: `Swal.getConfirmButton().click();`
                            })}
                        </div>
                    </div>
                `,
            }).then((resultado) => {
                if (resultado.isConfirmed) {
                    datos_consulta.forzar = true;
                    ejecutarConsultaAntecedentes(datos_consulta);
                }
            });
        } else if (CODIGO === 200 && !RESPUESTA.existe) {
            mostrarToast('success', RESPUESTA.message);
            setTimeout(() => {
                mostrarResultadoAntecedentes();
            }, 500);
        } else {
            mostrarToast('danger', RESPUESTA.message || 'Ocurrió un error al consultar los antecedentes');
        }
    } catch (error) {
        Swal.close();

        let mensaje_error = 'Ocurrió un error al consultar los antecedentes';

        if (error.responseJSON) {
            if (error.responseJSON.message) {
                mensaje_error = error.responseJSON.message;
            } else if (error.responseJSON.errors) {
                mensaje_error = Object.values(error.responseJSON.errors).flat().join(', ');
            }
        }

        mostrarToast('danger', mensaje_error);
    }
}

