public function obtenerDatosParticipanteProceso(Request $request): ?Proceso {
    return $this->modelo::select('id', 'empresa_id', 'usuario_id', 'estado_id', 'prioridad_id', 'base_datos_antigua_id', 'nombre', 'fecha_inicio', 'fecha_cierre', 'cantidad_vacantes', 'capturar_camara', 'capturar_video', 'mostrar_logo_aplicante', 'dias_vencimiento_agendas', 'fecha_vencimiento_agendas', 'favorito', 'activo', 'created_at')
        ->where('id', $request->proceso_id)
        ->when(
            !$request->filled('todos_los_estados') || !filter_var($request->todos_los_estados, FILTER_VALIDATE_BOOLEAN),
            fn($consulta) => $consulta->where('estado_id', EstadoProceso::ACTIVO_ID)
        )
        ->when($request->filled('incluir_etapa_usuario') && filter_var($request->incluir_etapa_usuario, FILTER_VALIDATE_BOOLEAN), function ($consulta) {
            $consulta->with(['etapaUsuario:etapas.id,nombre']);
        })
        ->with([
            'empresa:id,razon_social',
            'estado:id,nombre',
            'prioridad:id,nombre',
            'pruebas:id,nombre,slug,duracion',
            'agendas' => function ($consulta_agendas) use ($request) {
                $consulta_agendas->select('id', 'agenda_id', 'proceso_id', 'prueba_id', 'evaluador_id', 'evaluado_id', 'estado_id', 'fecha_inicio', 'fecha_cierre', 'fecha_procesamiento', 'perfil_id', 'ajuste')
                    ->where('evaluado_id', $request->participante_id)
                    ->whereHas('prueba', function ($consulta_prueba) use ($request) {
                        $consulta_prueba->whereHas('procesosPruebas', function ($consulta_procesos_pruebas) use ($request) {
                            $consulta_procesos_pruebas->where('proceso_id', $request->proceso_id);
                        });
                    })
                    ->with([
                        'estado:id,nombre',
                        'perfil:id,nombre',
                        'prueba:id,nombre,slug',
                        'prueba.procesosPruebas' => function ($consulta_procesos_pruebas) use ($request) {
                            $consulta_procesos_pruebas->select('id', 'prueba_id', 'perfil_id', 'proceso_id', 'porcentaje', 'created_at', 'updated_at')
                                ->where('proceso_id', $request->proceso_id)
                                ->with('perfil:id,nombre');
                        }
                    ]);
            }
        ])
        ->orderBy('created_at', 'DESC')
        ->orderBy('favorito', 'ASC')
        ->get()
        ->each(function ($proceso) {
            $proceso->append('duracion_total_pruebas');
        })
        ->first();
}

/**
 * Obtener un proceso.
 *
 * @param int $id ID del proceso.
 * @return ?Proceso
 * @author Daniel Beltrán
 * @author Sergio Vargas
 * @author Andres Gonzalez
 */
public function getUno(int $id): ?Proceso {
    return $this->modelo::select('id', 'oferta_laboral_id', 'empresa_id', 'usuario_id', 'estado_id', 'prioridad_id', 'vacante_id', 'base_datos_antigua_id', 'nombre', 'fecha_inicio', 'fecha_cierre', 'cantidad_vacantes', 'capturar_camara', 'capturar_video', 'mostrar_logo_aplicante', 'dias_vencimiento_agendas', 'fecha_vencimiento_agendas', 'favorito', 'visibilidad', 'activo', 'created_at')
    ->with([
        'empresa:id,razon_social',
        'usuario:id,nombres,apellidos',
        'estado:id,nombre',
        'prioridad:id,nombre',
        'pruebas:id,nombre,slug,duracion'
    ])
    ->withCount('seleccionados')
    ->withTrashed()
    ->find($id)
    ->append('duracion_total_pruebas');
}

/**
 * Obtener un proceso en base a filtros avanzados.
 *
 * @param Request $request Contenido de la petición.
 * @return ?Proceso
 * @author Daniel Beltrán
 * @author Fahibram Cárcamo
 * @author Sergio Vargas
 * @author Esperanza Olivo
 */
public function getUnoAvanzado(Request $request): ?Proceso {
