/**
 * Crear card de candidato con etapas y puntajes.
 *
 * @param {Object} aplicante Datos del aplicante con usuario y etapas.
 * @returns {string} HTML de la card del candidato.
 * @author Andrés Morales
 * @author José Manuel Jiménez
 * @author Jair Carvajal
 * @author Andres Gonzalez
 * @author Esperanza Olivo
 */
function crearCardCandidatoResultados(aplicante) {
    var usuario = aplicante.usuario;
    var etapas = aplicante.etapas;

    var adecuacion = aplicante.adecuacion;
    var borde_color = '';
    var etiqueta_estilo = '';

    if (aplicante.adecuacion !== null) {
        if (adecuacion <= ADECUACION_CALIFICACION_BAJA) {
            borde_color = 'borde-indice-talento-rojo';
            etiqueta_estilo = 'badge-indice-talento-rojo';
        } else if (adecuacion <= ADECUACION_CALIFICACION_MEDIA) {
            borde_color = 'borde-indice-talento-amarillo';
            etiqueta_estilo = 'badge-indice-talento-amarillo';
        } else {
            borde_color = 'borde-indice-talento-verde';
            etiqueta_estilo = 'badge-indice-talento-verde';
        }
    }

    let etapas_html = etapas
        .filter(etapa => etapa.nombre_etapa !== 'Contratados' && etapa.nombre_etapa !== 'Descartados')
        .map(etapa => {
            let puntaje_final = etapa.puntaje !== null ? etapa.puntaje : etapa.puntaje_ia;

            let clase_etiqueta = 'bg-secondary-subtle';
            if (puntaje_final !== null) {
                if (puntaje_final >= 75) {
                    clase_etiqueta = 'tag-tonal-green';
                } else if (puntaje_final >= 50) {
                    clase_etiqueta = 'tag-tonal-yellow';
                } else {
                    clase_etiqueta = 'tag-tonal-red';
                }
            }

            var texto_puntaje = puntaje_final !== null
                ? `${puntaje_final}%`
                : (etapa.nombre_etapa === 'Documentos para contratación' ? 'Pendiente' : 'N/A');

            if (etapa.nombre_etapa == 'Documentos para contratación') {
                texto_puntaje = `${etapa?.archivos_solicitados?.archivos_guardados.length || 0} de ${etapa?.archivos_solicitados?.documentos.length || 0} Adjuntos`;
                clase_etiqueta = 'bg-info-subtle';
            }

            return `
                <div class="col text-center d-flex flex-column">
                    <small class="text-gray-30 text-label-2 fw-semibold mb-2">${etapa.nombre_etapa}</small>
                    ${crearTag({
                        class: `${clase_etiqueta} fw-semibold`,
                        texto: texto_puntaje
                    })}
                </div>
            `;
        }).join('');

    return `
        <div class="card">
            <div class="card-body">
                <div class="d-flex align-items-center">
                    <div class="me-3">
                        ${crearCheckbox({
                            id: `checkbox-candidato-${usuario.id}`,
                            name: 'checkbox_candidatos_resultados',
                            value: usuario.id,
                            class: 'checkbox-tabla-componente',
                            checked: window[nombre_tabla_resultados + '_seleccionados'].some(item => item.usuario.id == usuario.id),
                            onchange: `seleccionarElemento(${usuario.id}, this.checked, '${nombre_tabla_resultados}');`
                        })}
                    </div>
                    <div class="position-relative me-3">
                        <img src="/usuarios-imagen/${usuario.id}" class="rounded-circle pointer ${borde_color}" width="60" height="60" onclick="verDetalleCandidato(${usuario.id})">
                        ${(adecuacion !== null) ? `<span class="candidato-badge text-label-1 badge ${etiqueta_estilo} position-absolute">${adecuacion}%</span>` : ''}
                    </div>
                    <div>
                        <h5 class="mb-1 fw-semibold">
                            <label class="text-headline-4 text-gray-10 cursor-pointer" onclick="verDetalleCandidato(${usuario.id})">
                                ${usuario.nombres} ${usuario.apellidos}
                            </label>
                        </h5>
                        <div class="d-flex flex-wrap gap-5 text-label-2 text-gray-30">
                            <span><i class="text-body-2 bi bi-envelope me-2"></i> ${usuario.email || 'N/A'}</span>
                            <span><i class="text-body-2 bi bi-telephone me-2"></i> ${usuario.telefono || 'N/A'}</span>
                        </div>
                    </div>
                    <div class="ms-auto">
                        ${crearBoton({
                            clases: 'btn-outline-primary btn-circle me-2',
                            texto: '<i class="bi bi-person-plus"></i>',
                            onclick: `modalAsignarCandidatoOtraVacante(${usuario.id})`
                        })}
                        ${crearBoton({
                            clases: 'btn-outline-primary btn-circle',
                            texto: '<i class="bi bi-file-earmark-person"></i>',
                        })}
                    </div>
                </div>
                <hr>
                <div class="d-flex flex-wrap gap-3">
                    ${etapas_html}
                </div>
            </div>
        </div>
    `;
}

/**
 * Renderizar botones de acciones masivas.
 *
 * @param {string} nombre_tabla Nombre de la tabla.
 * @returns {string} HTML con los botones de acciones.
 * @author Andrés Morales
 */
function renderizarBotonesAcciones(nombre_tabla) {
    return `
        <div class="col-12 componentes-botones-adicionales-${nombre_tabla}">
            <div class="row">
                <div class="col-auto me-5 px-3">
                    ${crearCheckbox({
                        id: `checkbox-seleccionar-todos-${nombre_tabla}`,
                        onchange: `seleccionarTodos(this.checked, '${nombre_tabla}');`,
                        label: `<span id="${nombre_tabla}-seleccionados-total">Seleccionado: 0</span>`,
                    })}
                </div>
                <div class="col-auto px-1">
                    ${crearBoton({
                        id: `boton-descartar_${nombre_tabla}`,
                        clases: 'btn-outline-danger',
                        texto: '<i class="bi bi-person-fill-x text-body-1 me-2"></i> Descartar',
                        disabled: true,
                        onclick: `descartarCandidatos(null, '${nombre_tabla}')`
                    })}
                </div>
            </div>
        </div>
    `;
}

/**
 * Seleccionar o deseleccionar todos los candidatos.
 *
 * @param {boolean} comprobado Chequear o deschequear.
 * @param {string} nombre_tabla Nombre de la tabla.
 * @returns {void}
 * @author Andrés Morales
 */
async function seleccionarTodos(comprobado, nombre_tabla) {
    window[nombre_tabla + '_seleccionados'] = [];
    if (comprobado) {
        for (var i = 0; i < window[nombre_tabla + '_ids'].length; i++) {
            window[nombre_tabla + '_seleccionados'].push(window[nombre_tabla + '_ids'][i]);
        }
    }
    actualizarDatatables(nombre_tabla);
    validarSeleccionados(nombre_tabla);
}

/**
 * Seleccionar o deseleccionar un candidato.
 *
 * @param {number} entrante_id ID del aplicante seleccionado.
 * @param {boolean} comprobado Chequear o deschequear.
 * @param {string} nombre_tabla Nombre de la tabla.
 * @returns {void}
 * @author Andrés Morales
 */
function seleccionarElemento(entrante_id, comprobado, nombre_tabla) {
    if (comprobado) {
        if (!window[nombre_tabla + '_seleccionados'].some(item => item.usuario.id == entrante_id)) {
            var objeto = window[nombre_tabla + '_ids'].find(item => item.usuario.id == entrante_id);
            if (objeto) {
                window[nombre_tabla + '_seleccionados'].push(objeto);
            }
        }
    } else {
        window[nombre_tabla + '_seleccionados'] = window[nombre_tabla + '_seleccionados'].filter(item => item.usuario.id != entrante_id);
    }
    validarSeleccionados(nombre_tabla);
}

/**
 * Validar candidatos seleccionados y actualizar UI.
 *
 * @param {string} nombre_tabla Nombre de la tabla.
 * @returns {void}
 * @author Andrés Morales
 */
function validarSeleccionados(nombre_tabla) {
    if (window[nombre_tabla + '_seleccionados'].length == 0) {
        $(`#btn-exportar-${nombre_tabla}`).html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar todo`);
        $(`#checkbox-seleccionar-todos-${nombre_tabla}`).prop('indeterminate', false);
        $(`#checkbox-seleccionar-todos-${nombre_tabla}`).prop('checked', false);
    } else if (window[nombre_tabla + '_seleccionados'].length == window[nombre_tabla + '_ids'].length) {
        $(`#btn-exportar-${nombre_tabla}`).html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar seleccionado`);
        $(`#checkbox-seleccionar-todos-${nombre_tabla}`).prop('indeterminate', false);
        $(`#checkbox-seleccionar-todos-${nombre_tabla}`).prop('checked', true);
    } else {
        $(`#btn-exportar-${nombre_tabla}`).html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar seleccionado`);
        $(`#checkbox-seleccionar-todos-${nombre_tabla}`).prop('indeterminate', true);
    }
    habilitarBotonesAcciones(nombre_tabla);
    $(`#${nombre_tabla}-seleccionados-total`).text('Seleccionado: ' + window[nombre_tabla + '_seleccionados'].length);
}

/**
 * Habilitar o deshabilitar botones de acciones masivas.
 *
 * @param {string} nombre_tabla Nombre de la tabla.
 * @returns {void}
 * @author Andrés Morales
 */
function habilitarBotonesAcciones(nombre_tabla) {
    var habilitado = window[nombre_tabla + '_seleccionados'].length > 0;

    $(`#boton-descartar_${nombre_tabla}`).prop('disabled', !habilitado);

    actualizarEstadoBotonesComparacion();
}

/**
 * Actualizar estado de botones de comparación según candidatos seleccionados.
 *
 * @returns {void}
 * @author Andrés Morales
 */
function actualizarEstadoBotonesComparacion() {
    var candidatos_seleccionados = window[nombre_tabla_resultados + '_seleccionados'] || [];
    var cantidad_seleccionados = candidatos_seleccionados.length;
    var boton_comparativo = $('#btn-comparativo-basico');

    if (cantidad_seleccionados >= 2) {
        boton_comparativo.prop('disabled', false).removeClass('disabled');
    } else {
        boton_comparativo.prop('disabled', true).addClass('disabled');
    }
}

/**
 * Generar comparativo básico de candidatos seleccionados.
 * Envía una petición POST al servidor con los IDs de los candidatos seleccionados
 * y la vacante actual para obtener el reporte PDF comparativo.
 *
 * @returns {void}
 * @author Andrés Morales
 */
function comparativoBasico() {
    var candidatos_seleccionados = window[nombre_tabla_resultados + '_seleccionados'] || [];

    if (candidatos_seleccionados.length < 2) {
        mostrarAlerta('warning', 'Debe seleccionar al menos 2 candidatos para realizar el comparativo');
        return;
    }

    // Extraer los IDs de usuario de los candidatos seleccionados
    var usuarios_ids = candidatos_seleccionados.map(item => item.usuario.id);

    // Crear formulario para enviar POST y abrir PDF en nueva ventana
    var formulario = document.createElement('form');
    formulario.method = 'POST';
    formulario.action = '/vacantes-comparativo-basico-aplicantes';
    formulario.target = '_blank';

    // Agregar token CSRF
    var csrf_input = document.createElement('input');
    csrf_input.type = 'hidden';
    csrf_input.name = '_token';
    csrf_input.value = $('meta[name="csrf-token"]').attr('content');
    formulario.appendChild(csrf_input);

    // Agregar vacante_id
    var vacante_input = document.createElement('input');
    vacante_input.type = 'hidden';
    vacante_input.name = 'vacante_id';
    vacante_input.value = VACANTE_ID;
    formulario.appendChild(vacante_input);

    // Agregar usuarios_ids (array)
    usuarios_ids.forEach(function(usuario_id) {
        var usuario_input = document.createElement('input');
        usuario_input.type = 'hidden';
        usuario_input.name = 'usuarios_ids[]';
        usuario_input.value = usuario_id;
        formulario.appendChild(usuario_input);
    });

    // Agregar formulario al body y enviarlo
    document.body.appendChild(formulario);
    formulario.submit();
    document.body.removeChild(formulario);

    // Mostrar mensaje de éxito
    mostrarToast('success', 'Generando reporte comparativo...');
}

/**
 * Función para identificar los mejores candidatos utilizando IA.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function identificarMejoresCandidatos() {
    usuarios_comparados_ia = [];
    let seleccionados_ia = window[nombre_tabla_resultados + '_seleccionados'];
    let usuarios_ids = [];
    $.each(seleccionados_ia, function(indice, candidato) {
        usuarios_ids.push(candidato.usuario.id);
