/**
 * Reprocesar la videoentrevista con IA, limpiando resultados previos.
 *
 * @param {number} etapa_vacante_usuario_id ID de la etapa vacante usuario.
 * @returns {void}
 * @author Sergio Vargas
 */
function reprocesarVideoentrevista(etapa_vacante_usuario_id) {
    $.ajax({
        url: `/api/reprocesar-videoentrevista/${etapa_vacante_usuario_id}`,
        type: 'POST',
        dataType: 'json',
        data: { _token: $('meta[name="csrf-token"]').attr('content') },
        success: function(respuesta) {
            mostrarToast('success', respuesta.message);
        },
        error: function(error) {
            mostrarToast('danger', error.responseJSON?.errors || 'Ocurrió un error al reprocesar.');
        }
    });
}

/**
 * Reproducir un video específico en el reproductor.
 *
 * @param {number} video_id ID del video a reproducir.
 * @param {number} parte Parte del video que se está reproduciendo.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function reproducirVideoEntrevista(video_id, parte) {
    $('#reproductor-videoentrevista').prop('src', '/archivos-abrir/' + video_id);
    $('#reproductor-videoentrevista')[0].play();
}

