/**
 * Crear una pregunta en el contenedor de preguntas
 *
 * @param {object} pregunta Objeto de la pregunta.
 * @param {number} numero_pregunta Número de la pregunta.
 * @param {object} etapa Objeto de la etapa.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 * @author Andres Gonzalez
 */
function crearPregunta(pregunta, etapa) {
    pregunta.tipo_pregunta = obtenerTipoPregunta(pregunta);
    return `
        <div class="col-12 pregunta prefiltro rounded-3 border px-4 pt-4 mb-4" data-tipo_pregunta="${pregunta.tipo_pregunta}" data-pregunta_id="${pregunta.id}" data-puntaje="${pregunta?.puntaje?.puntaje}" data-puntaje_ia="${pregunta?.puntaje?.puntaje_ia}">
            <div class="row">
                <div class="col-12 text-body-2 text-gray-10 mb-2">
                    Pregunta ${pregunta.tipo_pregunta == 'abierta' ? 'abierta' : ''} ${pregunta.tipo_pregunta == 'seleccion_multiple' ? 'selección múltiple' : ''} ${pregunta.tipo_pregunta == 'seleccion_unica' ? 'selección única' : ''}
                </div>
                <div class="col-12 text-body-3 text-gray-30 mb-3">${pregunta.enunciado}</div>
            </div>
            <div class="row mt-3 respuestas">${crearRespuesta(pregunta, etapa)}</div>
        </div>
    `;
}

/**
 * Crear el componente de opciones de respuestas según el tipo de pregunta
 * @param {object} pregunta Objeto de la pregunta.
 * @param {object} etapa Objeto de la etapa.
 * @returns {string} Componente de opciones de respuestas.
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function crearRespuesta(pregunta, etapa) {
    let etapa_actual = detalle_usuario?.etapa_actual?.etapa?.nombre === etapa.nombre_etapa;

    if (pregunta.tipo_pregunta == 'abierta') {
        return `
            <div class="col-12 text-body-2 text-gray-10 mb-2">Respuesta</div>
            <div class="col-12 text-body-3 text-gray-30 mb-3">
                ${pregunta?.respuestas[0]?.respuesta || ''}
            </div>
            <div class="col-12 text-body-2 text-gray-10 mb-2 border-top pt-3 mb-3">
                <div class="row justify-content-between align-items-center">
                    <div class="col-auto">
                        <div class="row align-items-center">
                            <div class="col-auto">
                                Puntuación dada por IA
                            </div>
                            <div class="col-auto pe-0 py-2">
                                ${crearAlerta(`${pregunta.puntaje.puntaje_ia && pregunta.puntaje.puntaje_ia > 0 ? 'success' : 'danger'}`, `${pregunta.puntaje.puntaje_ia || 0} pt`, 'py-2 px-3')}
                            </div>
                        </div>
                    </div>
                    <div class="col-auto contenedor-puntuacion-reclutador">
                        <div class="row align-items-center">
                            <div class="col-auto">
                                Puntuación dada por reclutador
                            </div>
                            <div class="col-auto puntuacion-reclutador">
                                ${pregunta?.puntaje?.puntaje != null ?
                                    `${crearAlerta(`${pregunta?.puntaje?.puntaje && pregunta?.puntaje?.puntaje > 0 ? 'success' : 'danger'}`, `${pregunta?.puntaje?.puntaje || 0} pt`, 'py-2 px-3')}`
                                : ''}
                            </div>
                        </div>
                        <div class="row justify-content-center align-items-center">
                            <div class="col-auto ps-0 py-2">
                                <div class="row align-items-center">
                                    <div class="col">
                                        ${crearBoton({
                                            clases: `btn-text-primary btn-circle ${pregunta?.puntaje?.puntaje === 1 ? 'selected' : ''}`,
                                            texto: '<i class="bi bi-check-square-fill text-state-green"></i>',
                                            onclick: `seleccionarOpcionRespuesta(${pregunta.id}, true, this)`,
                                            tooltip: crearTooltip({
                                                content: 'Marcar como correcta',
                                                placement: 'top'
                                            }),
                                            disabled: !etapa_actual
                                        })}
                                    </div>
                                    <div class="col">
                                        ${crearBoton({
                                            clases: `btn-text-primary btn-circle ${pregunta?.puntaje?.puntaje === 0 ? 'selected' : ''}`,
                                            texto: '<i class="bi bi-x-square-fill text-state-red"></i>',
                                            onclick: `seleccionarOpcionRespuesta(${pregunta.id}, false, this)`,
                                            tooltip: crearTooltip({
                                                content: 'Marcar incorrecta',
                                                placement: 'top'
                                            }),
                                            disabled: !etapa_actual
                                        })}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        `;
    } else {
        return `
            <div class="col-12 text-body-2 text-gray-10 mb-2">Respuesta del candidato</div>
            <div class="col-12 text-body-3 text-gray-30 mb-3">
                ${pregunta.opciones.map(opcion =>
                    crearCard({
                        nombre_grupo: `opcion_pregunta_${pregunta.id}`,
                        id: opcion.id,
                        contenido: opcion.texto,
                        contenido_class: pregunta.respuestas.some(respuesta => respuesta.opcion_pregunta_id === opcion.id) ? `${opcion.es_correcta === 1 ? `${pregunta.tipo_pregunta == 'seleccion_unica' ? 'text-state-green' : 'text-state-green'}` : `${pregunta.tipo_pregunta == 'seleccion_unica' ? 'text-state-red' : 'text-state-red'}`}` : '',
                        class: pregunta.respuestas.some(respuesta => respuesta.opcion_pregunta_id === opcion.id) ? `${opcion.es_correcta === 1 ? `${pregunta.tipo_pregunta == 'seleccion_unica' ? 'radio-state-green' : 'check-state-green'}` : `${pregunta.tipo_pregunta == 'seleccion_unica' ? 'radio-state-red' : 'check-state-red'}`}` : '',
                        tipo: pregunta.tipo_pregunta == 'seleccion_unica' ? 'radio' : 'checkbox',
                        onchange: 'validarBotonSiguiente();',
                        checked: pregunta.respuestas.some(respuesta => respuesta.opcion_pregunta_id === opcion.id),
                        disabled: true,
                    })
                ).join('')}
            </div>
            <div class="col-12 text-body-2 text-gray-10 mb-2 border-top pt-3 mb-3">
                Correctas
            </div>
            <div class="col-12">
                ${pregunta.opciones.filter(opcion => opcion.es_correcta == 1).map(opcion => `
                    <div class="row align-items-center">
                        <div class="col-auto">
                            ${pregunta.tipo_pregunta == 'seleccion_unica' ?
                                crearRadioButton({
                                    disabled: true,
                                }) : crearCheckbox({
                                    disabled: true,
                                })
                            }
                        </div>
                        <div class="col-auto px-0">
                            ${opcion.texto}
                        </div>
                    </div>
                `).join('')}
            </div>
            <div class="col-12 text-body-2 text-gray-10 mb-2 border-top pt-3 mb-3">
                <div class="row align-items-center">
                    <div class="col-auto">
                        Puntuación obtenida
                    </div>
                    <div class="col-auto px-0 py-2">
                        ${crearAlerta(`${pregunta.puntaje.puntaje && pregunta.puntaje.puntaje == 1 ? 'success' : 'danger'}`, `${pregunta.puntaje.puntaje || 0} pt`, 'py-2 px-3')}
                    </div>
                </div>
            </div>
        `;
    }
}

/**
 * Mostrar el resultado de la etapa de preguntas prefiltro.
 *
 * @param {Object} etapa Etapa de la vacante.
 * @returns {string} Código HTML del resultado de la etapa.
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function mostrarPreguntasPrefiltro(etapa) {
    let preguntas = etapa.preguntas || [];
    if (etapa.puntaje == null && etapa.puntaje_ia == null) {
        return `
            <div class="col-12">
                <div class="row justify-content-center my-14">
                    <div class="col-auto">
                        <i class="bi bi-file-text text-gray-60 icono-sin-completar-etapa"></i>
                    </div>
                    <div class="col-12 text-center text-headline-5">
                        Este candidato aún no ha completado las<br>preguntas prefiltro
                    </div>
                </div>
            </div>
        `;
    } else {
        let contenido_preguntas = '';
        $.each(preguntas, function(indice, pregunta) {
            contenido_preguntas += crearPregunta(pregunta, etapa);
        });

        let total_puntos = mostrarPuntajeTotalPrefiltro();

        contenido_preguntas += `
            <div class="col-12 text-end mb-4">
                <div class="row justify-content-between">
                    <div class="col-auto text-headline-4 text-gray-10">
                        Total
                    </div>
                    <div class="col-auto">
                        <div class="row">
                            <div class="col-auto pe-0 py-2">
                                ${crearTag({
                                    texto: `<i class="bi bi-dot text-state-green"></i> Se requieren más de ${etapa.cantidad_preguntas_correctas} pt`,
                                    class: 'tag-tonal-gray',
                                })}
                            </div>
                            <div class="col-auto pe-0 py-2" id="contenedor-total-puntos-prefiltro">${crearAlerta(`${total_puntos >= parseInt(etapa.cantidad_preguntas_correctas) ? 'success' : 'warning'}`, `${total_puntos} pt`, 'py-2 px-3')}</div>
                        </div>
                    </div>
                </div>
            </div>
        `;
        return contenido_preguntas;
    }
}

/**
 * Obtener el tipo de pregunta según sus características
 *
 * @param {object} pregunta Objeto de la pregunta.
 * @returns {string} Tipo de pregunta.
 * @author José Manuel Jiménez
 */
function obtenerTipoPregunta(pregunta) {
    if (pregunta.es_abierta == 1) {
        return 'abierta';
    } else {
        let cantidades_correctas = 0;
        pregunta.opciones.forEach(function(opcion) {
            if (opcion.es_correcta == 1) {
                cantidades_correctas++;
            }
        });
        if (cantidades_correctas == 1) {
            return 'seleccion_unica';
        } else {
            return 'seleccion_multiple';
        }
    }
}

/**
 * Seleccionar opción de respuesta para pregunta abierta.
 *
 * @param {number} pregunta_id ID de la pregunta.
 * @param {boolean} es_correcta Indica si la respuesta es correcta.
 * @param {object} elemento Elemento HTML del botón seleccionado.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function seleccionarOpcionRespuesta(pregunta_id, es_correcta, elemento) {
    $(elemento).closest('.row').find('.btn-circle').removeClass('selected');
    $(elemento).addClass('selected');
    let puntaje = es_correcta ? 1 : 0;
    $.ajax({
        url: `/guardar-puntaje-pregunta-reclutador`,
        type: 'POST',
        dataType: 'json',
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
            pregunta_id: pregunta_id,
            puntaje: puntaje,
            usuario_id: usuario_detalle_id
        },
        success: function(respuesta) {
            if (es_correcta) {
                $(elemento).closest('.contenedor-puntuacion-reclutador').find('.puntuacion-reclutador').empty().append(`
                    ${crearAlerta('success', '1 pt', 'py-2 px-3')}
                `);
                mostrarToast('success', 'El candidato gana 1 punto.');
            } else {
                $(elemento).closest('.contenedor-puntuacion-reclutador').find('.puntuacion-reclutador').empty().append(`
                    ${crearAlerta('danger', '0 pt', 'py-2 px-3')}
                `);
                mostrarToast('success', 'El candidato no obtiene puntos.');
            }
            mostrarPuntajeTotalPrefiltro();
        },
        error: function() {
            mostrarToast('danger', 'Error al guardar la respuesta.');
        }
    });
}

/**
 * Mostrar el puntaje total actualizado en la etapa de preguntas prefiltro.
 *
 * @returns {number} Puntaje total.
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 */
function mostrarPuntajeTotalPrefiltro() {
    let total_puntos = 0;

    if ($('#contenedor-total-puntos-prefiltro').length > 0) {
        $('.pregunta.prefiltro').each(function() {
            let puntaje    = parseInt($(this).data('puntaje'));
            let puntaje_ia = parseInt($(this).data('puntaje_ia'));

            if (puntaje !== null && !isNaN(puntaje)) {
                total_puntos += puntaje;
            } else if (puntaje_ia !== null && !isNaN(puntaje_ia)) {
                total_puntos += puntaje_ia;
            }
        });

        let etapa_preguntas_prefiltro = detalle_usuario.etapas.find(etapa => etapa.nombre_etapa === 'Preguntas prefiltro');

        $('#contenedor-total-puntos-prefiltro').empty().append(`
            ${crearAlerta(`${total_puntos >= parseInt(etapa_preguntas_prefiltro.cantidad_preguntas_correctas) ? 'success' : 'warning'}`, `${total_puntos} pt`, 'py-2 px-3')}
        `);
    }

    return total_puntos;
}

/**
 * Mostrar el resultado de la etapa de prueba técnica.
 *
 * @param {Object} etapa Etapa de la vacante.
 * @returns {string} Código HTML del resultado de la etapa.
 * @author José Manuel Jiménez
 * @author Jair Carvajal
 * @author Andres Gonzalez
 */
