/**
 * Adjuntar documentos para contratación.
 *
 * @param {number} etapa_vacante_usuario_id ID de la etapa vacante usuario.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function adjuntarDocumentosContratacion(etapa_vacante_usuario_id) {
    let formulario_datos = new FormData();
    formulario_datos.append('etapa_vacante_usuario_id', etapa_vacante_usuario_id);
    let archivo = $('#documentos_contratacion')[0].files[0];
    formulario_datos.append('archivo', archivo);
    let nombre_documento = archivo.name;
    formulario_datos.append('nombre_documento', 'cliente_empresa_' + nombre_documento);
    $.ajax({
        url: `/vacantes-guardar-documentos-solicitados`,
        type: 'POST',
        data: formulario_datos,
        processData: false,
        contentType: false,
        headers: {
            'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
        },
        success: function(respuesta) {
            mostrarToast('success', 'Documento adjuntado correctamente.');
            $.ajax({
                url: `/vacantes-detalle-aplicante/${VACANTE_ID}/${usuario_detalle_id}`,
                type: 'GET',
                dataType: 'json',
                success: function(datos) {
                    let etapa_documentos_contratacion = datos.data.etapas.find(etapa => etapa.nombre_etapa === 'Documentos para contratación');
                    let cuerpo_acordeon = $('[data-nombre_etapa="Documentos para contratación"]').find('.accordion-body');
                    cuerpo_acordeon.empty().append(mostrarResultadoDocumentosContratacion(etapa_documentos_contratacion))
                }
            });
        },
        error: function() {
            mostrarToast('danger', 'Error al adjuntar el documento.');
        }
    });
}

