 */
function modalCompartirAcceso(usuario) {
    $.ajax({
        url : `/generar-acceso-usuario/${usuario.id}`,
        type: 'POST',
        data: {
            _token: $('meta[name="csrf-token"]').attr('content')
        }
    }).done((respuesta) => {
        $('#enlace-acceso').attr('href', respuesta.data.enlace + '?vacante_id='+VACANTE_ID);
        $('#enlace-acceso').text(respuesta.data.enlace + '?vacante_id='+VACANTE_ID);
        $('.enlace-acceso').data('texto', respuesta.data.enlace + '?vacante_id='+VACANTE_ID);
    }).fail((error) => {
        mostrarToast('danger', 'Ocurrió un error al generar el enlace de acceso');
    });

    $('#modal-compartir-acceso #imagen_usuario').attr('src', '/usuarios-imagen/'+usuario.id);
    $('#modal-compartir-acceso #nombre').html(`ID ${usuario.id} - ${usuario.nombre}`);
    $('#modal-compartir-acceso #correo').html(`<i class="bi bi-envelope me-2"></i> ${usuario.email}`);
    $('#modal-detalle-resultados').modal('hide');
    $('#modal-compartir-acceso').modal('show');
}

