 * Mostrar el modal para asignar candidato a otra vacante.
 *
 * @param {number} usuario_id ID del usuario.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function modalAsignarCandidatoOtraVacante(usuario_id) {
    clonar_usuario_id = usuario_id;
    $.ajax({
        url: `/vacantes-listado-tabla`,
        data: {
            activo: 1
        },
        type: 'GET',
        dataType: 'json',
        success: function(datos) {
            let vacantes = datos.data;
            $('#asignar_vacante_id').empty().append(
                `<option value="">Selecciona una vacante</option>` + vacantes.map(vacante => `
                    <option value="${vacante.id}">${vacante.nombre_vacante || ''}</option>
                `).join('')
            );
        }
    });
    $('#modal-asignar-candidato-otra-vacante').modal('show');
}

/**
 * Clonar aplicante de una vacante a otra.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function clonarAplicante() {
    if ($('#asignar_vacante_id').val() == '') {
        mostrarToast('danger', 'Debes seleccionar una vacante.');
    } else {
        $.ajax({
            url: '/vacantes-clonar-aplicante',
            type: 'POST',
            data: {
                _token          : $('meta[name="csrf-token"]').attr('content'),
                vacante_id      : VACANTE_ID,
                nueva_vacante_id: $('#asignar_vacante_id').val(),
                usuario_id      : clonar_usuario_id
            }
        }).done((respuesta) => {
            mostrarToast('success', respuesta.message);
            $('#modal-asignar-candidato-otra-vacante').modal('hide');
        }).fail((error) => {
            mostrarToast('danger', error.responseJSON?.message);
        });
    }
}

/**
 * Ver formato de entrevista.
 *
 * @param {number} etapa_id ID de la etapa de entrevista.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function verFormatoEntrevista(etapa_id) {
    window.open(`/formatos-entrevistas/${etapa_id}`, '_blank');
}

/**
 * Ajustar altura de lista de videos dinámicamente según el tamaño de pantalla.
 * Calcula la altura disponible basándose en el viewport height y aplica
 * un límite máximo responsivo al contenedor de la lista de videos.
 *
 * @returns {void}
 * @author Jair Carvajal
 */
function ajustarAlturaListaVideos() {
    var contenedor = document.getElementById('contenedor-lista-videos');
    if (!contenedor) return;
    var altura_viewport = window.innerHeight;
    var altura_maxima = altura_viewport * 0.6;
    contenedor.style.maxHeight = `${altura_maxima}px`;
}

/**
 * Descargar reportes de una etapa específica.
 *
 * @param {Object} datos_etapa Objeto con los datos de la etapa.
 * @returns {void}
 * @author Andres Gonzalez
 */
function descargarReportesEtapa(datos_etapa) {
    if (datos_etapa.nombre_etapa === 'Pruebas psicométricas') {
        descargarReportesPsicometricos(datos_etapa);
    } else {
        descargarArchivosEtapa(datos_etapa);
    }
}

/**
 * Descargar reportes psicométricos de una etapa.
 *
 * @param {Object} etapa Objeto con los datos de la etapa.
 * @returns {void}
 * @author Andres Gonzalez
 */
function descargarReportesPsicometricos(etapa) {
    let agendas = etapa?.proceso?.agendas || [];

    if (agendas.length === 0) {
        mostrarToast('warning', 'No hay agendas disponibles para descargar');
        return;
    }

    let agendas_ids = agendas.map(agenda => agenda.id);

    Swal.fire({
        showCloseButton: true,
        closeButtonHtml: '<i class="bi bi-x text-headline-4 text-gray-20"></i>',
        showConfirmButton: false,
        showDenyButton: false,
        showCancelButton: false,
        html: `
            <div class="row w-100 mx-0 mt-2">
                <div class="col-12 fw-semibold text-start text-gray-10 text-headline-4">Descargar reportes</div>
                <div class="col-12 mt-3 text-start text-body-2 fw-normal">
                    ¿Está seguro que desea descargar ${agendas_ids.length} reporte${agendas_ids.length > 1 ? 's' : ''} en un archivo ZIP?
                    <br><small class="text-gray-30">Este proceso puede tardar algunos minutos dependiendo de la cantidad de reportes.</small>
                </div>
                <div class="col-6 mt-4 mb-2">
                    ${crearBoton({
                        clases: 'btn-outline-primary w-100 justify-content-center',
                        texto: 'Cancelar',
                        onclick: 'Swal.close();'
                    })}
                </div>
                <div class="col-6 mt-4 mb-2">
                    ${crearBoton({
                        id: 'btn-confirmar-descarga-zip',
                        clases: 'btn-primary w-100 justify-content-center',
                        texto: 'Descargar',
                        onclick: 'Swal.clickConfirm();'
                    })}
                </div>
            </div>
        `,
    }).then((resultado) => {
        if (resultado.isConfirmed) {
            descargarReportesPsicometricosZip(agendas_ids);
        }
    });
}

/**
 * Descargar múltiples reportes psicométricos en formato ZIP.
 *
 * @param {Array} agendas_ids Array de IDs de agendas de pruebas psicométricas.
 * @returns {void}
 * @author Andres Gonzalez
 */
async function descargarReportesPsicometricosZip(agendas_ids) {
    Swal.fire({
        title: 'Generando reportes...',
        html: `
            <div class="d-flex justify-content-center align-items-center my-4">
                <div class="spinner-border text-primary me-3" role="status">
                    <span class="visually-hidden">Cargando...</span>
                </div>
                <span class="text-body-2">Procesando ${agendas_ids.length} reporte${agendas_ids.length > 1 ? 's' : ''}. Por favor espere...</span>
            </div>
        `,
        allowOutsideClick: false,
        allowEscapeKey: false,
        showConfirmButton: false
    });

    try {
        let formulario = $('<form>', {
            method: 'POST',
            action: '/reportes-agendas-zip'
        });

        formulario.append($('<input>', {
            type: 'hidden',
            name: '_token',
            value: $('input[name="_token"]').val()
        }));

        agendas_ids.forEach(function(agendaId) {
            formulario.append($('<input>', {
                type: 'hidden',
                name: 'agendas_ids[]',
                value: agendaId
            }));
        });

        $('body').append(formulario);
        formulario.submit();

        setTimeout(function() {
            formulario.remove();
            Swal.close();
            mostrarToast('success', 'Descarga iniciada. El archivo se descargará automáticamente.');
        }, 1000);

    } catch (error) {
        Swal.close();
        mostrarToast('danger', 'Error al iniciar la descarga. Inténtelo nuevamente.');
    }
}

/**
 * Descargar archivos de una etapa.
 *
 * @param {Object} datos_etapa Objeto con los datos de la etapa.
 * @returns {void}
 * @author Andres Gonzalez
 */
function descargarArchivosEtapa(datos_etapa) {
    if (!datos_etapa || !datos_etapa.id) {
        mostrarToast('danger', 'Error: No se encontró el ID de la etapa');
        return;
    }

    Swal.fire({
        title: 'Generando archivo...',
        html: `
            <div class="d-flex justify-content-center align-items-center my-4">
                <div class="spinner-border text-primary me-3" role="status">
                    <span class="visually-hidden">Cargando...</span>
                </div>
                <span class="text-body-2">Preparando descarga de archivos. Por favor espere...</span>
            </div>
        `,
        allowOutsideClick: false,
        allowEscapeKey: false,
        showConfirmButton: false
    });

    try {
        let formulario = $('<form>', {
            method: 'POST',
            action: `/vacantes-exportar-archivos-aplicante/${datos_etapa.id}`
        });

        formulario.append($('<input>', {
            type: 'hidden',
            name: '_token',
            value: $('input[name="_token"]').val()
        }));

        $('body').append(formulario);
        formulario.submit();

        setTimeout(function() {
            formulario.remove();
            Swal.close();
            mostrarToast('success', 'Descarga iniciada. El archivo se descargará automáticamente.');
        }, 1000);

    } catch (error) {
        Swal.close();
        mostrarToast('danger', 'Error al iniciar la descarga. Inténtelo nuevamente.');
    }
}

