            const TIPO_DOCUMENTO   = $('#tipo_documento_antecedente').val();
            const NUMERO_DOCUMENTO = $('#numero_documento_antecedente').val().trim();
            const NOMBRE_COMPLETO  = $('#nombre_completo_antecedente').val().trim();
            const FECHA_EXPEDICION = $('#fecha_expedicion_antecedente').val();

            if (!TIPO_DOCUMENTO) {
                mostrarToast('warning', 'Por favor selecciona el tipo de documento');
                return false;
            }

            if (!NUMERO_DOCUMENTO) {
                const TEXTO = TIPO_DOCUMENTO === 'NOMBRE' ? 'el nombre completo' : 'el número de documento';
                mostrarToast('warning', `Por favor ingresa ${TEXTO}`);
                return false;
            }

            if ((TIPO_DOCUMENTO === 'INT' || TIPO_DOCUMENTO === 'PP') && !NOMBRE_COMPLETO) {
                mostrarToast('warning', 'Por favor ingresa el nombre completo');
                return false;
            }

            const DATOS = {
                tipo_documento: TIPO_DOCUMENTO,
                documento: NUMERO_DOCUMENTO
            };

            if (TIPO_DOCUMENTO === 'INT' || TIPO_DOCUMENTO === 'PP') {
                DATOS.nombre = NOMBRE_COMPLETO;
            }

            if (FECHA_EXPEDICION) {
                DATOS.fecha_expedicion = FECHA_EXPEDICION;
            }

            return DATOS;
        }
    }).then((resultado) => {
        if (resultado.isConfirmed && resultado.value) {
            ejecutarConsultaAntecedentes(resultado.value);
        }
    });
}

/**
 * Ejecutar consulta de antecedentes.
 *
 * @param {Object} datos_consulta Datos de la consulta {tipo_documento, documento, fecha_expedicion}.
 * @returns {Promise<void>}
 * @author Andres González
 */
async function ejecutarConsultaAntecedentes(datos_consulta) {
    Swal.fire({
        title: 'Consultando antecedentes...',
        html: '<div class="spinner-border text-primary" role="status"></div><p class="mt-3">Por favor espera un momento</p>',
        allowOutsideClick: false,
        showConfirmButton: false
    });

    try {
        const DATOS_ENVIO = {
            _token:         $('input[name="_token"]').val(),
            tipo_documento: datos_consulta.tipo_documento,
            documento:      datos_consulta.documento
        };

        if (datos_consulta.nombre) {
            DATOS_ENVIO.nombre = datos_consulta.nombre;
        }

        if (datos_consulta.fecha_expedicion) {
            DATOS_ENVIO.fecha_expedicion = datos_consulta.fecha_expedicion;
        }

        if (datos_consulta.forzar) {
            DATOS_ENVIO.forzar = true;
        }

        if (detalle_usuario.id) {
            DATOS_ENVIO.aplicante_id = detalle_usuario.id;
        }

        const RESPUESTA = await $.ajax({
            url: '/antecedentes-consultar',
            type: 'POST',
            data: DATOS_ENVIO
        });

        Swal.close();

        const CODIGO = RESPUESTA.codigo || 200;

        if (CODIGO === 200 && RESPUESTA.existe) {
            Swal.fire({
                showCloseButton: true,
                closeButtonHtml: '<i class="bi bi-x text-headline-4 text-gray-20"></i>',
                showConfirmButton: false,
                showDenyButton: false,
                showCancelButton: false,
                html: `
                    <div class="row w-100 mx-0 mt-2">
                        <div class="col-12 fw-semibold text-start text-gray-10 text-headline-4">
                            Consulta existente
                        </div>
                        <div class="col-12 mt-4 text-start text-body-2 fw-normal text-gray-30">
                            ${RESPUESTA.message}
                        </div>
                        <div class="col-12 mt-3 text-start text-body-2 fw-normal text-gray-30">
                            ¿Deseas realizar una nueva consulta de todas formas?
                        </div>
                        <div class="col-6 mt-5 mb-2">
                            ${crearBoton({
                                clases: 'btn-outline-primary w-100 justify-content-center',
                                texto: 'No',
                                onclick: `Swal.close();`
                            })}
                        </div>
                        <div class="col-6 mt-5 mb-2">
                            ${crearBoton({
                                clases: 'btn-primary w-100 justify-content-center',
                                texto: 'Sí, consultar',
                                onclick: `Swal.getConfirmButton().click();`
                            })}
                        </div>
                    </div>
                `,
            }).then((resultado) => {
                if (resultado.isConfirmed) {
                    datos_consulta.forzar = true;
                    ejecutarConsultaAntecedentes(datos_consulta);
                }
            });
        } else if (CODIGO === 200 && !RESPUESTA.existe) {
            mostrarToast('success', RESPUESTA.message);
            setTimeout(() => {
                mostrarResultadoAntecedentes();
            }, 500);
        } else {
            mostrarToast('danger', RESPUESTA.message || 'Ocurrió un error al consultar los antecedentes');
        }
    } catch (error) {
        Swal.close();

        let mensaje_error = 'Ocurrió un error al consultar los antecedentes';

        if (error.responseJSON) {
            if (error.responseJSON.message) {
                mensaje_error = error.responseJSON.message;
            } else if (error.responseJSON.errors) {
                mensaje_error = Object.values(error.responseJSON.errors).flat().join(', ');
            }
        }

        mostrarToast('danger', mensaje_error);
    }
}

