/**
 * Función para realizar una pregunta sobre los candidatos recomendados utilizando IA.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function preguntaCandidatoRecomendadosIA() {
    let seleccionados_ia = window[nombre_tabla_resultados + '_seleccionados'];
    let usuarios_ids = [];
    $.each(seleccionados_ia, function(indice, candidato) {
        usuarios_ids.push(candidato.usuario.id);
    });
    let pregunta = obtenerDatosClassicEditor('comentario_comparacion');
    if (usuarios_ids.length > 1 && pregunta.trim() != '') {
        $('#titulo-generando-ia').text(`Generando ${usuarios_ids.length} candidatos...`);
        $('#modal-generando-ia').modal('show');
        $.ajax({
            url: `/preguntar-candidatos-recomendados`,
            data: {
                _token: $('input[name="_token"]').val(),
                vacante_id: VACANTE_ID,
                candidatos: usuarios_comparados_ia,
                pregunta: pregunta
            },
            type: 'POST',
            success: function (respuesta) {
                let respuesta_comentario = respuesta.data.respuesta;
                $('#contenedor-comentarios-comparacion-ia').append(`
                    <div class="row mb-5 comentario-ia">
                        <div class="col-auto">
                            <img src="/usuarios-imagen/${USUARIO.id}" class="rounded-circle border" width="50" height="50">
                        </div>
                        <div class="col ps-0">
                            <div class="col-12 px-4 pt-4 bg-white rounded-4 shadow-1">
                                <div class="row">
                                    <div class="col-12 text-label-2 text-gray-10">${USUARIO.nombre_completo}</div>
                                    <div class="col-12 text-body-3">${pregunta}</div>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div class="row mb-5">
                        <div class="col pe-0">
                            <div class="col-12 px-4 pt-4 bg-white rounded-4 shadow-1">
                                <div class="row">
                                    <div class="col-12 text-label-2 text-gray-10">IA</div>
                                    <div class="col-12 text-body-3 pb-2">${respuesta_comentario}</div>
                                </div>
                            </div>
                        </div>
                        <div class="col-auto">
                            <img src="/iconos/icono_ia.svg" class="rounded-circle bg-state-yellow border p-1" width="50" height="50">
                        </div>
                    </div>
                `);
                let comentarios_ia = $('#contenedor-comentarios-comparacion-ia').children('.comentario-ia').length;
                $('#comentarios-ia').removeClass('d-none').text(comentarios_ia);
                $('#contenedor-comentarios-comparacion-ia').removeClass('d-none');
