/**
 * Crear tag de estado de agenda con tooltip si el estado requiere fechas.
 *
 * @param {object} agenda Objeto agenda con estado_id, fecha_inicio y fecha_cierre.
 * @returns {string} HTML del tag con o sin tooltip.
 * @author Sergio Vargas
 * @author José Manuel Jiménez
 */
function crearTagEstadoAgenda(agenda) {
    let estados_configuraciones = {
        '1': { texto: 'Sin iniciar', class: 'px-4 text-center text-label-1 tag-tonal-blue', mostrar_fechas: true },
        '2': { texto: 'Iniciada', class: 'px-4 text-center text-label-1 tag-tonal-yellow', mostrar_fechas: true },
        '3': { texto: 'Finalizada', class: 'px-4 text-center text-label-1 tag-tonal-green', mostrar_fechas: false },
        '4': { texto: 'Expirada', class: 'px-4 text-center text-label-1 tag-tonal-red', mostrar_fechas: true },
        '5': { texto: 'Invalidada', class: 'px-4 text-center text-label-1 tag-tonal-gray', mostrar_fechas: false },
        '6': { texto: 'Sin pago', class: 'px-4 text-center text-label-1 tag-tonal-purple', mostrar_fechas: false },
    };
    let estado_id = String(agenda.estado_id);
    let configuracion = estados_configuraciones[estado_id];
    if (!configuracion) {
        return crearTag({ texto: 'Desconocido', class: 'px-4 text-center text-label-1 tag-tonal-gray' });
    }
    let contenido_tooltip = '';
    if (configuracion.mostrar_fechas && agenda.fecha_inicio && agenda.fecha_cierre) {
        let fecha_inicio_formateada = convertirFecha(agenda.fecha_inicio);
        let fecha_cierre_formateada = convertirFecha(agenda.fecha_cierre);
        contenido_tooltip = `Fecha inicio: ${fecha_inicio_formateada}<br>Fecha fin: ${fecha_cierre_formateada}`;
    }
    if (contenido_tooltip) {
        return `
            <div class="tag ${configuracion.class} text-label-1" data-bs-toggle="tooltip" data-bs-html="true" data-bs-placement="top" title="${contenido_tooltip}">
                ${configuracion.texto}
            </div>
        `;
    } else {
        return crearTag({ texto: configuracion.texto, class: configuracion.class });
    }
}

/**
 * Obtener el tag de recomendación para una agenda psicométrica según su puntaje y tipo de prueba.
 * Tipos 2,3,7,12,19: 0-59 no recomendado, 60-75 con sugerencias, 76-100 recomendado.
 * Tipo 4 (IQ Factorial): 0-79 no recomendado, 80-89 con sugerencias, 90-135 recomendado.
 *
 * @param {Object} agenda Objeto agenda con prueba.id y ajuste.
 * @returns {string} HTML del tag de recomendación o cadena vacía.
 * @author Jair Carvajal
 */
function obtenerTagRecomendacionPsicometrica(agenda) {
    if (agenda.estado_id !== 3 || agenda.ajuste === null) return '';

    const IQ_FACTORIAL_ID = 4;
    const es_iq           = agenda.prueba.id === IQ_FACTORIAL_ID;
    let texto, clase;

    if (es_iq) {
        if (agenda.ajuste <= 79)      { texto = 'No recomendado';              clase = 'tag-filled-smooth-red'; }
        else if (agenda.ajuste <= 89) { texto = 'Recomendado con sugerencias'; clase = 'tag-filled-yellow';     }
        else                          { texto = 'Recomendado';                 clase = 'tag-filled-green';      }
    } else {
        if (agenda.ajuste <= 59)      { texto = 'No recomendado';              clase = 'tag-filled-smooth-red'; }
        else if (agenda.ajuste <= 75) { texto = 'Recomendado con sugerencias'; clase = 'tag-filled-yellow';     }
        else                          { texto = 'Recomendado';                 clase = 'tag-filled-green';      }
    }

    return `<div class="mt-1">${crearTag({ texto, class: clase })}</div>`;
}

/**
 * Reprocesar una agenda finalizada.
 *
 * @param {number} agenda_id ID de la agenda
 * @param {string} nombre_tabla Nombre de la tabla
 * @returns {void}
 * @author Sergio Vargas
 * @author Andres Gonzalez
 */
function reprocesarAgenda(agenda_id, nombre_tabla) {
    Swal.fire({
        showCloseButton: true,
        closeButtonHtml: '<i class="bi bi-x text-headline-4 text-gray-20"></i>',
        showConfirmButton: false,
        showDenyButton: false,
        showCancelButton: false,
        html: `
            <div class="row w-100 mx-0 mt-2">
                <div class="col-12 fw-semibold text-start text-gray-10 text-headline-4">¿Reprocesar agenda?</div>
                <div class="col-12 mt-5 text-start text-body-2 fw-normal">
                    Esta acción volverá a procesar los resultados de la agenda.
                </div>
                <div class="col-4 mt-5 mb-2">
                    ${crearBoton({
                        clases: 'btn-outline-primary w-100 justify-content-center',
                        texto: 'Cancelar',
                        onclick: `Swal.close();`
                    })}
                </div>
                <div class="col-4 mt-5 mb-2">
                    ${crearBoton({
                        clases: 'btn-primary w-100 justify-content-center',
                        texto: 'Solo reprocesar',
                        onclick: `Swal.clickConfirm();`
                    })}
                </div>
                <div class="col-4 mt-5 mb-2">
                    ${crearBoton({
                        clases: 'btn-tonal-primary w-100 justify-content-center',
                        texto: 'Reprocesar y enviar correo',
                        onclick: `Swal.clickDeny();`
                    })}
                </div>
            </div>
        `,
    }).then((resultado) => {
        if (resultado.isConfirmed || resultado.isDenied) {
            let enviar_correo = resultado.isDenied;
            $.ajax({
                url: `/agendas-reprocesar/${agenda_id}`,
                type: 'POST',
                data: {
                    enviar_notificacion_correo: enviar_correo,
                    _token: $('meta[name="csrf-token"]').attr('content')
                },
                success: function(respuesta) {
                    if (respuesta.message) {
                        mostrarToast('success', respuesta.message);
                        if (nombre_tabla) {
                            actualizarDatatables(nombre_tabla);
                            actualizarDatatables(nombre_tabla_resultados);
                        }
                    }
                },
                error: function(xhr) {
                    let mensaje = 'Error al reprocesar la agenda.';
                    if (xhr.responseJSON && xhr.responseJSON.message) {
                        mensaje = xhr.responseJSON.message;
                    }
                    mostrarToast('danger', mensaje);
                }
            });
        }
    });
}

/**
 * Abrir el modal de videograbación y mostrar los videos asociados a la agenda.
 *
 * @param {number} agenda_id ID de la agenda.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function abrirModalVideograbacion(agenda_id) {
    $.ajax({
        url: `/archivos`,
        data: {
            modelo_id: agenda_id,
            modelo: "App\\Models\\Agendas\\Agenda",
            nombre: 'video'
        },
        type: 'GET',
        success: function (respuesta) {
            let videos = respuesta.data;
            $('#reproduciendo-parte').text('1');
            $('#reproductor').attr('src', '');
            $('#lista-videos').empty();
            if (videos.length == 0) {
                $('#sin-videos').removeClass('d-none');
                $('#videos').addClass('d-none');
            } else {
                $('#sin-videos').addClass('d-none');
                $('#videos').removeClass('d-none');
            }
            for (let i = 0; i < videos.length; i++) {
                if (i == 0) {
                    $('#reproductor').prop('src', '/archivos-abrir/' + videos[i].id);
                }
                $('#lista-videos').append(`
                    <div class="w-100 text-label-1 fw-semibold text-gray-10" onclick="reproducirVideo(${videos[i].id}, ${i + 1});">
                        Parte ${i + 1}:
                        <video class="w-100 rounded-3 pointer">
                            <source src="/archivos-abrir/${videos[i].id}" type="video/mp4">
                            Tu navegador no soporta el elemento de video.
                        </video>
                    </div>
                `);
            }
            $('#modal-detalle-participante').modal('hide');
            $('#modal-vidograbaciones').modal('show');
            // Ajustar altura de lista de videos después de mostrar el modal
            setTimeout(ajustarAlturaListaVideos, 100);
        },
        error: function (error) {
            mostrarToast('danger', 'Error al cargar la videograbación.');
        }
    });
}

