/**
 * Crear una pregunta en el contenedor de preguntas
 *
 * @param {object} pregunta Objeto de la pregunta.
 * @param {number} numero_pregunta Número de la pregunta.
 * @param {object} etapa Objeto de la etapa.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 * @author Andres Gonzalez
 */
function crearPregunta(pregunta, etapa) {
    pregunta.tipo_pregunta = obtenerTipoPregunta(pregunta);
    return `
        <div class="col-12 pregunta prefiltro rounded-3 border px-4 pt-4 mb-4" data-tipo_pregunta="${pregunta.tipo_pregunta}" data-pregunta_id="${pregunta.id}" data-puntaje="${pregunta?.puntaje?.puntaje}" data-puntaje_ia="${pregunta?.puntaje?.puntaje_ia}">
            <div class="row">
                <div class="col-12 text-body-2 text-gray-10 mb-2">
                    Pregunta ${pregunta.tipo_pregunta == 'abierta' ? 'abierta' : ''} ${pregunta.tipo_pregunta == 'seleccion_multiple' ? 'selección múltiple' : ''} ${pregunta.tipo_pregunta == 'seleccion_unica' ? 'selección única' : ''}
                </div>
                <div class="col-12 text-body-3 text-gray-30 mb-3">${pregunta.enunciado}</div>
            </div>
            <div class="row mt-3 respuestas">${crearRespuesta(pregunta, etapa)}</div>
        </div>
    `;
}

/**
 * Crear el componente de opciones de respuestas según el tipo de pregunta
 * @param {object} pregunta Objeto de la pregunta.
 * @param {object} etapa Objeto de la etapa.
 * @returns {string} Componente de opciones de respuestas.
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function crearRespuesta(pregunta, etapa) {
    let etapa_actual = detalle_usuario?.etapa_actual?.etapa?.nombre === etapa.nombre_etapa;

    if (pregunta.tipo_pregunta == 'abierta') {
        return `
