/**
 * Actualizar el puntaje de la prueba técnica.
 *
 * @param {number} etapa_vacante_usuario_id ID de la etapa vacante usuario.
 * @param {number} puntaje Puntaje a actualizar.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function actualizarPuntajePruebaTecnica(etapa_vacante_usuario_id, puntaje) {
    const puntaje_limpio = `${puntaje ?? ''}`.trim();

    if (puntaje_limpio === '') {
        return;
    }

    if (!/^\d+$/.test(puntaje_limpio)) {
        mostrarToast('warning', 'El puntaje debe ser un número entero entre 0 y 100.');
        return;
    }

    const puntaje_numero = Number(puntaje_limpio);
    if (puntaje_numero < 0 || puntaje_numero > 100) {
        mostrarToast('warning', 'El puntaje debe estar entre 0 y 100.');
        return;
    }

    if (ACTUALIZACIONES_PUNTAJE_EN_CURSO[etapa_vacante_usuario_id]) {
        return;
    }

    ACTUALIZACIONES_PUNTAJE_EN_CURSO[etapa_vacante_usuario_id] = true;

    $.ajax({
        url: `/guardar-puntaje-adecuacion-reclutador`,
        type: 'POST',
        dataType: 'json',
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
            id: etapa_vacante_usuario_id,
            puntaje: puntaje_numero,
        },
        success: function(respuesta) {
            if (respuesta?.errors) {
                mostrarToast('danger', respuesta.errors);
                return;
            }

            mostrarToast('success', respuesta?.message || 'Puntaje actualizado correctamente.');
            setTimeout(() => window.location.reload(), 700);
        },
        error: function(error, estado_peticion) {
            if (estado_peticion === 'abort' || error?.statusText === 'abort') {
                return;
            }

            mostrarToast(
                'danger',
                error?.responseJSON?.errors || error?.responseJSON?.message || 'Error al actualizar el puntaje.'
            );
        },
        complete: function() {
            ACTUALIZACIONES_PUNTAJE_EN_CURSO[etapa_vacante_usuario_id] = false;
        }
    });
}

/**
