/**
 * Obtiene el ícono correspondiente a una extensión de archivo
 *
 * @param {string} extension Extensión del archivo
 * @returns {string} Clase del ícono correspondiente
 * @author José Manuel Jiménez
 */
function obtenerIconoPorExtension(extension) {
    switch (extension) {
        case 'pdf':
            return 'bi bi-filetype-pdf';
        case 'doc':
        case 'docx':
            return 'bi bi-filetype-docx';
        case 'xls':
        case 'xlsx':
            return 'bi bi-filetype-xlsx';
        default:
            return 'bi bi-file-earmark';
    }
}

/**
 * Mostrar el resultado de la etapa de documentos para contratación.
 *
 * @returns {string} Código HTML del resultado de la etapa.
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function mostrarResultadoDocumentosContratacion(etapa) {
    let archivos_contratacion = etapa?.archivos_solicitados?.archivos_guardados || [];

    // Si fecha_ejecucion es null, solo mostrar archivos cargados por la empresa (prefijo cliente_empresa_)
    if (etapa.fecha_ejecucion == null) {
        archivos_contratacion = archivos_contratacion.filter(archivo => archivo.nombre.startsWith('cliente_empresa_'));
    }

    $('#contenedor-archivos-contratacion').empty();
    let documentos_contratacion = [];
    let imagenes_cargadas = [];
    archivos_contratacion.forEach((archivo) => {
        let extension = archivo.nombre_original_archivo.split('.').pop().toLowerCase();
        let es_imagen = ['jpg', 'jpeg', 'png', 'gif', 'webp'].includes(extension);
        if (es_imagen) {
            imagenes_cargadas.push(archivo);
        } else {
            documentos_contratacion.push(archivo);
        }
    });
    let archivos_html = '';
    documentos_contratacion.forEach((archivo) => {
        let extension = archivo.nombre_original_archivo.split('.').pop().toLowerCase();
        let icono = obtenerIconoPorExtension(extension);
        let url_archivo = `/archivos-abrir/${archivo.id}`;
        archivos_html += `
            <div class="col-auto archivo-item">
                <div class="col-auto px-3 border rounded-2">
                    <div class="row align-items-center">
                        <div class="col-auto py-3">
                            <i class="${icono} text-blue-40"></i>
                        </div>
                        <div class="col px-0 py-3">
                            <a href="${url_archivo}"
                               target="_blank"
                               class="text-blue-40 text-decoration-none nombre-archivo-contratacion"
                               ${crearTooltip({placement: 'top', content: archivo.nombre_original_archivo, toggle: 'popover'})}>
                                ${archivo.nombre_original_archivo}
                            </a>
                        </div>
                        <a class="col-auto" href="${url_archivo}" download>
                            <i class="bi bi-download text-blue-40 pointer"></i>
                        </a>
                    </div>
                </div>
            </div>
        `;
    });
    imagenes_cargadas.forEach((archivo) => {
        let url_imagen = `/archivos-abrir/${archivo.id}`;
        archivos_html += `
            <div class="col-auto archivo-item">
                <div class="col-auto px-3 border rounded-2 contenedor-archivo-imagen">
                    <div class="row align-items-center">
                        <img class="col-12 border-bottom px-0 pointer imagen-archivo-previsualizacion" src="${url_imagen}" alt="${archivo.nombre_original_archivo}" onclick="mostrarPrevisualizacionImagen('${url_imagen}')">
                    </div>
                    <div class="row align-items-center">
                        <div class="col pe-0 py-3 text-blue-40 nowrap" ${crearTooltip({placement: 'top', content: archivo.nombre_original_archivo, toggle: 'popover'})}>
                            ${archivo.nombre_original_archivo}
                        </div>
                        <a class="col-auto" href="${url_imagen}" download>
                            <i class="bi bi-download text-blue-40 pointer"></i>
                        </a>
                    </div>
                </div>
            </div>
        `;
    });
    if (etapa.fecha_ejecucion == null && archivos_contratacion.length == 0) {
        $('#contenedor-cantidad-adjuntos').empty();
        setTimeout(() => {
            if (etapa.id != null) {
                $('#contenedor-cantidad-adjuntos').empty().append(
                    crearTag({texto: '', class: 'tag-tonal-blue cantidad-adjuntos'})
                );

                let archivos_aplicante = etapa.archivos_solicitados.archivos_guardados.filter(archivo => !archivo.nombre.startsWith('cliente_empresa_'));
                let tipos_documentos_cargados = [...new Set(archivos_aplicante.map(archivo => archivo.nombre))];
                $('.cantidad-adjuntos').text(`${tipos_documentos_cargados.length} de ${etapa.archivos_solicitados.documentos.length} adjuntos`);
            }
        }, 100);
        return `
            <div class="col-12">
                <div class="row justify-content-center my-14">
                    <div class="col-auto">
                        <i class="bi bi-filetype-pdf text-gray-60 icono-sin-completar-etapa"></i>
                    </div>
                    <div class="col-12 text-center text-headline-5">
                        Este candidato aún no ha adjuntado los documentos para contratación
                    </div>
                    ${etapa.id != null ? `
                        <div class="col-auto mt-10">
                            ${crearBoton({
                                clases: 'btn-outline-primary',
                                texto: '<i class="bi bi-link-45deg"></i> Adjuntar archivos',
                                onclick: "$('#documentos_contratacion').click();"
                            })}
                            <input type="file" id="documentos_contratacion" accept="application/pdf,.doc,.docx,.xls,.xlsx" class="d-none" onchange="adjuntarDocumentosContratacion(${etapa.id})">
                        </div>
                    ` : ''}
                </div>
            </div>
        `;
    } else {
        setTimeout(() => {
            $('#contenedor-cantidad-adjuntos').empty().append(
                crearTag({texto: '', class: 'tag-tonal-blue cantidad-adjuntos'})
            );

            let archivos_aplicante = etapa.archivos_solicitados.archivos_guardados.filter(archivo => !archivo.nombre.startsWith('cliente_empresa_'));
            let tipos_documentos_cargados = [...new Set(archivos_aplicante.map(archivo => archivo.nombre))];
            $('.cantidad-adjuntos').text(`${tipos_documentos_cargados.length} de ${etapa.archivos_solicitados.documentos.length} Adjuntos`);
        }, 100);
        return `
            <div class="col-12">
                <div class="border rounded-4 p-4 mb-4 position-relative">
                    <div class="col-12">
                        <div class="row justify-content-between align-items-center mb-4">
                            <div class="col-auto text-body-2 text-gray-10">
                                Archivos adjuntos
                            </div>
                            <div class="col-auto">
                                ${crearBoton({
                                    clases: 'btn-outline-primary',
                                    texto: '<i class="bi bi-link-45deg"></i> Adjuntar archivos',
                                    onclick: `$('#documentos_contratacion').click();`
                                })}
                                <input type="file" id="documentos_contratacion" accept="application/pdf,.doc,.docx,.xls,.xlsx" class="d-none" onchange="adjuntarDocumentosContratacion(${etapa.id})">
                            </div>
                        </div>
                    </div>
                    <div class="row g-3" id="contenedor-archivos-contratacion">${archivos_html}</div>
                </div>
            </div>
        `;
    }
}

/**
 * Adjuntar documentos para contratación.
 *
 * @param {number} etapa_vacante_usuario_id ID de la etapa vacante usuario.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function adjuntarDocumentosContratacion(etapa_vacante_usuario_id) {
    let formulario_datos = new FormData();
    formulario_datos.append('etapa_vacante_usuario_id', etapa_vacante_usuario_id);
    let archivo = $('#documentos_contratacion')[0].files[0];
    formulario_datos.append('archivo', archivo);
    let nombre_documento = archivo.name;
    formulario_datos.append('nombre_documento', 'cliente_empresa_' + nombre_documento);
    $.ajax({
        url: `/vacantes-guardar-documentos-solicitados`,
        type: 'POST',
        data: formulario_datos,
        processData: false,
        contentType: false,
        headers: {
            'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
        },
        success: function(respuesta) {
            mostrarToast('success', 'Documento adjuntado correctamente.');
            $.ajax({
                url: `/vacantes-detalle-aplicante/${VACANTE_ID}/${usuario_detalle_id}`,
                type: 'GET',
                dataType: 'json',
                success: function(datos) {
                    let etapa_documentos_contratacion = datos.data.etapas.find(etapa => etapa.nombre_etapa === 'Documentos para contratación');
                    let cuerpo_acordeon = $('[data-nombre_etapa="Documentos para contratación"]').find('.accordion-body');
                    cuerpo_acordeon.empty().append(mostrarResultadoDocumentosContratacion(etapa_documentos_contratacion))
                }
            });
        },
        error: function() {
            mostrarToast('danger', 'Error al adjuntar el documento.');
        }
    });
}

